INSERT INTO `mdt_penal_codes` (`code`, `label`, `charge_class`, `months`, `fine`, `color`, `description`, `category`) VALUES
('A.M. 5001', 'Posse Irregular de Arma de Fogo', 'misdemeanor', 10, 2500, '#f91521', 'Manter arma de fogo em residência, propriedade ou local sob responsabilidade do agente sem registro, autorização ou documentação exigida pelas normas da cidade.', 'Armas e Munições'),
('A.M. 5002', 'Posse Irregular de Arma Registrada em Nome de Terceiro', 'misdemeanor', 12, 3000, '#f91521', 'Manter sob posse arma de fogo regularmente registrada, porém pertencente a terceiro, sem autorização legítima para sua guarda.', 'Armas e Munições'),
('A.M. 5003', 'Posse de Arma com Registro Vencido', 'infraction', 0, 1500, '#15f943', 'Manter arma de fogo cujo registro, licença ou documentação obrigatória esteja vencida, sem indício de utilização criminosa.', 'Armas e Munições'),
('A.M. 5004', 'Posse de Arma em Local Não Autorizado', 'misdemeanor', 8, 2000, '#f91521', 'Manter arma de fogo em local não autorizado pela licença ou registro aplicável.', 'Armas e Munições'),
('A.M. 5005', 'Arma Registrada sem Comprovação de Propriedade', 'infraction', 0, 1000, '#15f943', 'Não apresentar comprovação válida de registro ou propriedade de arma encontrada em local sob responsabilidade do agente.', 'Armas e Munições'),
('A.M. 5006', 'Porte Ilegal de Arma de Fogo', 'felony', 25, 6000, '#f9b115', 'Transportar, carregar ou portar arma de fogo em via pública ou local de acesso público sem autorização válida para porte.', 'Armas e Munições'),
('A.M. 5007', 'Porte de Arma com Licença Vencida', 'misdemeanor', 10, 2500, '#f91521', 'Portar arma de fogo em espaço público utilizando autorização de porte vencida ou irregular.', 'Armas e Munições'),
('A.M. 5008', 'Porte de Arma Fora das Condições Autorizadas', 'misdemeanor', 10, 2500, '#f91521', 'Portar arma de fogo em situação, local ou condição expressamente vedada pela autorização concedida.', 'Armas e Munições'),
('A.M. 5009', 'Porte Oculto Ilegal de Arma', 'felony', 25, 6500, '#f9b115', 'Portar deliberadamente arma de fogo de forma oculta sem autorização legal para porte.', 'Armas e Munições'),
('A.M. 5010', 'Porte Ostensivo Ilegal de Arma', 'felony', 20, 5500, '#f9b115', 'Portar ou exibir arma de fogo ostensivamente em espaço público sem autorização compatível.', 'Armas e Munições'),
('A.M. 5011', 'Porte de Arma em Área Restrita', 'felony', 30, 7500, '#f9b115', 'Ingressar ou permanecer armado sem autorização em instalação policial, governamental, hospitalar ou outra área oficialmente restrita.', 'Armas e Munições'),
('A.M. 5012', 'Porte de Arma Durante Evento Público', 'felony', 20, 5000, '#f9b115', 'Portar arma de fogo sem autorização específica durante evento, reunião ou situação de grande concentração de pessoas.', 'Armas e Munições'),
('A.M. 5013', 'Porte de Arma Sob Influência de Álcool', 'felony', 25, 6000, '#f9b115', 'Portar arma de fogo enquanto estiver sob influência de álcool em condição capaz de comprometer discernimento ou segurança.', 'Armas e Munições'),
('A.M. 5014', 'Porte de Arma Sob Influência de Drogas', 'felony', 30, 7500, '#f9b115', 'Portar arma de fogo enquanto estiver sob influência de substância psicoativa capaz de comprometer discernimento ou segurança.', 'Armas e Munições'),
('A.M. 5015', 'Posse de Arma com Numeração Suprimida', 'felony', 40, 10000, '#f9b115', 'Possuir arma de fogo cuja numeração, marcação ou elemento oficial de identificação tenha sido removido, raspado ou inutilizado.', 'Armas e Munições'),
('A.M. 5016', 'Porte de Arma com Numeração Suprimida', 'felony', 50, 12500, '#f9b115', 'Portar arma de fogo em espaço público com número de série ou identificação oficial adulterada, removida ou suprimida.', 'Armas e Munições'),
('A.M. 5017', 'Adulteração de Número de Série de Arma', 'felony', 55, 15000, '#f9b115', 'Raspar, remover, alterar, substituir ou adulterar deliberadamente número de série ou identificação oficial de arma de fogo.', 'Armas e Munições'),
('A.M. 5018', 'Posse de Arma Furtada', 'felony', 40, 10000, '#f9b115', 'Possuir, guardar ou manter arma de fogo sabendo ou devendo razoavelmente saber que é produto de furto.', 'Armas e Munições'),
('A.M. 5019', 'Posse de Arma Roubada', 'felony', 45, 12500, '#f9b115', 'Possuir, guardar ou manter arma de fogo sabendo ou devendo razoavelmente saber que é produto de roubo.', 'Armas e Munições'),
('A.M. 5020', 'Porte de Arma Furtada ou Roubada', 'felony', 55, 15000, '#f9b115', 'Portar arma de fogo em espaço público sabendo que o armamento é produto de roubo ou furto.', 'Armas e Munições'),
('A.M. 5021', 'Empréstimo Irregular de Arma', 'misdemeanor', 12, 3000, '#f91521', 'Entregar ou emprestar arma de fogo a pessoa não autorizada a possuir ou portar aquele armamento.', 'Armas e Munições'),
('A.M. 5022', 'Cessão de Arma a Pessoa Não Habilitada', 'felony', 20, 5000, '#f9b115', 'Fornecer, ceder ou disponibilizar arma de fogo a pessoa sem autorização legal ou capacidade exigida para seu uso.', 'Armas e Munições'),
('A.M. 5023', 'Entrega de Arma a Pessoa Intoxicada', 'felony', 30, 7500, '#f9b115', 'Entregar conscientemente arma de fogo a pessoa sob efeito evidente de álcool ou drogas.', 'Armas e Munições'),
('A.M. 5024', 'Negligência na Guarda de Arma', 'misdemeanor', 8, 2000, '#f91521', 'Deixar arma de fogo armazenada de maneira negligente, permitindo acesso indevido ou criando risco relevante a terceiros.', 'Armas e Munições'),
('A.M. 5025', 'Abandono de Arma de Fogo', 'felony', 15, 4000, '#f9b115', 'Abandonar deliberadamente arma de fogo em local público ou acessível a terceiros sem providenciar sua guarda adequada.', 'Armas e Munições'),
('A.M. 5026', 'Perda de Arma sem Comunicação', 'infraction', 0, 1500, '#15f943', 'Deixar de comunicar em prazo razoável a perda, extravio ou desaparecimento de arma regularmente registrada.', 'Armas e Munições'),
('A.M. 5027', 'Posse Irregular de Munição', 'misdemeanor', 5, 1500, '#f91521', 'Possuir munição de arma de fogo sem autorização compatível ou sem vínculo legítimo com arma regularmente possuída.', 'Armas e Munições'),
('A.M. 5028', 'Porte Irregular de Munição', 'misdemeanor', 7, 2000, '#f91521', 'Transportar munição em espaço público sem autorização ou justificativa legítima.', 'Armas e Munições'),
('A.M. 5029', 'Posse de Munição de Calibre Não Autorizado', 'felony', 15, 4000, '#f9b115', 'Possuir munição de calibre ou categoria cuja aquisição ou posse não esteja autorizada ao agente.', 'Armas e Munições'),
('A.M. 5030', 'Posse de Grande Quantidade de Munição sem Autorização', 'felony', 20, 5000, '#f9b115', 'Manter quantidade anormalmente elevada de munições sem autorização, origem legítima ou justificativa compatível.', 'Armas e Munições'),
('A.M. 5031', 'Comércio Ilegal de Munições', 'felony', 45, 12500, '#f9b115', 'Vender, trocar, fornecer ou distribuir munições sem autorização legal.', 'Armas e Munições'),
('A.M. 5032', 'Comércio Ilegal de Armas', 'felony', 60, 17500, '#f9b115', 'Vender, comprar para revenda, trocar ou distribuir armas de fogo sem autorização legal.', 'Armas e Munições'),
('A.M. 5033', 'Tráfico de Armas', 'felony', 90, 30000, '#f9b115', 'Participar de atividade organizada destinada à aquisição, transporte, armazenamento ou distribuição ilegal de armas de fogo.', 'Armas e Munições'),
('A.M. 5034', 'Tráfico de Munições', 'felony', 75, 25000, '#f9b115', 'Participar de atividade organizada destinada à aquisição, transporte ou distribuição ilegal de munições.', 'Armas e Munições'),
('A.M. 5035', 'Fabricação Ilegal de Arma de Fogo', 'felony', 70, 22500, '#f9b115', 'Fabricar, montar ou produzir arma de fogo sem licença ou autorização competente.', 'Armas e Munições'),
('A.M. 5036', 'Modificação Ilegal de Arma', 'felony', 40, 10000, '#f9b115', 'Modificar deliberadamente mecanismo ou características de arma de fogo de forma proibida ou destinada a dificultar sua identificação.', 'Armas e Munições'),
('A.M. 5037', 'Conversão Ilegal de Arma', 'felony', 55, 15000, '#f9b115', 'Alterar arma ou dispositivo para modificar ilegalmente sua capacidade de disparo ou categoria de funcionamento.', 'Armas e Munições'),
('A.M. 5038', 'Fabricação Ilegal de Munição', 'felony', 45, 12500, '#f9b115', 'Produzir ou montar munições sem autorização, licença ou controle exigido.', 'Armas e Munições'),
('A.M. 5039', 'Documentação Falsa de Arma', 'felony', 35, 10000, '#f9b115', 'Criar, utilizar, apresentar ou manter documento falso destinado a aparentar registro, propriedade ou autorização legítima de arma.', 'Armas e Munições'),
('A.M. 5040', 'Fraude para Obtenção de Porte ou Registro', 'felony', 40, 12500, '#f9b115', 'Utilizar declaração, documento, identidade ou informação falsa para obter registro, licença ou autorização relacionada a arma de fogo.', 'Armas e Munições'),
('A.M. 5041', 'Exibição Ameaçadora de Arma', 'felony', 20, 5000, '#f9b115', 'Exibir, apontar ou manipular arma de fogo de maneira deliberadamente intimidatória sem justificativa legítima.', 'Armas e Munições'),
('A.M. 5042', 'Apontar Arma contra Terceiro', 'felony', 30, 7500, '#f9b115', 'Apontar deliberadamente arma de fogo contra outra pessoa sem situação legítima de defesa ou atuação autorizada.', 'Armas e Munições'),
('A.M. 5043', 'Disparo de Arma em Local Público', 'felony', 30, 7500, '#f9b115', 'Efetuar disparo de arma de fogo em via ou local público sem justificativa legítima, independentemente de atingir pessoa.', 'Armas e Munições'),
('A.M. 5044', 'Disparo Negligente de Arma', 'felony', 20, 5000, '#f9b115', 'Efetuar disparo de arma de fogo por imprudência, negligência ou manuseio inadequado, criando risco a terceiros.', 'Armas e Munições'),
('A.M. 5045', 'Disparo Intencional em Direção a Pessoa', 'felony', 70, 20000, '#f9b115', 'Efetuar deliberadamente disparo de arma de fogo na direção de outra pessoa, sem que seja possível comprovar resultado morte.', 'Armas e Munições'),
('A.M. 5046', 'Tentativa de Homicídio com Arma de Fogo', 'felony', 100, 30000, '#f9b115', 'Utilizar arma de fogo com intenção direta de causar a morte de outra pessoa, não ocorrendo o resultado por circunstância alheia à vontade do agente.', 'Armas e Munições'),
('A.M. 5047', 'Homicídio com Arma de Fogo', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa mediante utilização de arma de fogo.', 'Armas e Munições'),
('A.M. 5048', 'Disparo contra Veículo Ocupado', 'felony', 65, 17500, '#f9b115', 'Efetuar deliberadamente disparo contra veículo sabendo ou tendo razoável conhecimento de que há pessoas em seu interior.', 'Armas e Munições'),
('A.M. 5049', 'Disparo contra Residência Ocupada', 'felony', 65, 17500, '#f9b115', 'Efetuar deliberadamente disparos contra residência ou imóvel sabendo que existem pessoas em seu interior.', 'Armas e Munições'),
('A.M. 5050', 'Uso de Arma na Prática de Crime', 'felony', 35, 10000, '#f9b115', 'Portar, exibir ou utilizar arma de fogo como instrumento para facilitar, garantir ou executar outra atividade criminosa.', 'Armas e Munições'),
('A.M. 5051', 'Fornecimento de Arma para Prática de Crime', 'felony', 45, 12500, '#f9b115', 'Fornecer conscientemente arma de fogo a terceiro sabendo que será utilizada na prática de atividade criminosa.', 'Armas e Munições'),
('A.M. 5052', 'Ocultação de Arma Utilizada em Crime', 'felony', 30, 7500, '#f9b115', 'Ocultar, transportar, destruir ou esconder arma sabendo que ela foi utilizada em atividade criminosa.', 'Armas e Munições'),
('A.M. 5053', 'Destruição ou Alteração de Arma para Ocultar Evidência', 'felony', 40, 10000, '#f9b115', 'Destruir, desmontar ou modificar arma utilizada em crime com objetivo de impedir sua identificação ou perícia.', 'Armas e Munições'),
('A.M. 5054', 'Falsa Comunicação de Furto ou Roubo de Arma', 'felony', 25, 7500, '#f9b115', 'Comunicar falsamente furto, roubo ou desaparecimento de arma com objetivo de ocultar sua transferência, venda, perda ou utilização irregular.', 'Armas e Munições'),
('A.M. 5055', 'Arsenal Ilegal', 'felony', 85, 30000, '#f9b115', 'Manter sob posse ou controle conjunto relevante de armas e munições ilegais em quantidade incompatível com uso pessoal autorizado.', 'Armas e Munições'),
('C.A.P. 8001', 'Desobediência a Agente Público', 'misdemeanor', 7, 1500, '#f91521', 'Recusar-se deliberadamente a cumprir ordem legítima e claramente comunicada por agente público no exercício regular de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8002', 'Desacato a Agente Público', 'misdemeanor', 5, 1250, '#f91521', 'Ofender, humilhar ou desrespeitar gravemente agente público em razão do exercício de sua função, causando perturbação relevante da atuação oficial.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8003', 'Perturbação de Atividade Oficial', 'misdemeanor', 7, 1500, '#f91521', 'Interferir de forma deliberada e persistente em atividade oficial realizada por agente público, sem emprego de violência.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8004', 'Obstrução de Abordagem', 'misdemeanor', 10, 2000, '#f91521', 'Dificultar deliberadamente abordagem, revista, identificação ou fiscalização realizada legitimamente por agente público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8005', 'Recusa de Identificação em Procedimento Legal', 'misdemeanor', 5, 1000, '#f91521', 'Recusar-se injustificadamente a fornecer identificação quando legalmente exigida durante procedimento oficial.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8006', 'Resistência Passiva à Detenção', 'misdemeanor', 10, 2000, '#f91521', 'Resistir de maneira não violenta ao cumprimento legítimo de detenção, condução ou prisão.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8007', 'Resistência Ativa à Prisão', 'felony', 20, 5000, '#f9b115', 'Utilizar força física ou oposição ativa para impedir ou dificultar prisão ou detenção legítima.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8008', 'Fuga Durante Abordagem', 'felony', 15, 3500, '#f9b115', 'Empreender fuga deliberada durante abordagem ou procedimento oficial após ordem legítima para permanecer no local.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8009', 'Fuga após Ordem de Prisão', 'felony', 25, 6000, '#f9b115', 'Tentar fugir ou evadir-se após comunicação clara de prisão ou detenção legítima.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8010', 'Ameaça contra Agente Público', 'felony', 20, 5000, '#f9b115', 'Ameaçar agente público de causar mal injusto e relevante em razão de sua função ou durante exercício oficial.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8011', 'Ameaça Armada contra Agente Público', 'felony', 35, 9000, '#f9b115', 'Ameaçar agente público utilizando arma de fogo, arma branca ou instrumento potencialmente letal.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8012', 'Intimidação de Agente Público', 'felony', 20, 5000, '#f9b115', 'Utilizar intimidação, perseguição ou demonstração de força para constranger agente público em razão de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8013', 'Coação de Agente Público', 'felony', 30, 7500, '#f9b115', 'Constranger agente público mediante violência ou grave ameaça a praticar, omitir ou alterar ato relacionado à função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8014', 'Agressão contra Agente Público', 'felony', 30, 7500, '#f9b115', 'Agredir fisicamente agente público durante ou em razão do exercício de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8015', 'Lesão Corporal contra Agente Público', 'felony', 40, 10000, '#f9b115', 'Causar deliberadamente lesão corporal relevante a agente público durante ou em razão de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8016', 'Lesão Corporal Grave contra Agente Público', 'felony', 55, 15000, '#f9b115', 'Causar deliberadamente lesão grave, incapacitante ou com risco significativo à vida de agente público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8017', 'Agressão Armada contra Agente Público', 'felony', 50, 15000, '#f9b115', 'Agredir agente público utilizando arma de fogo, arma branca ou outro instrumento potencialmente letal.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8018', 'Tentativa de Desarmar Agente Público', 'felony', 35, 10000, '#f9b115', 'Tentar retirar, tomar ou assumir controle da arma utilizada ou portada por agente público durante procedimento oficial.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8019', 'Subtração de Arma de Agente Público', 'felony', 50, 15000, '#f9b115', 'Subtrair arma pertencente ou confiada a agente público sem emprego de violência ou grave ameaça.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8020', 'Roubo de Arma de Agente Público', 'felony', 65, 20000, '#f9b115', 'Subtrair arma de agente público mediante violência, grave ameaça ou domínio sobre a vítima.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8021', 'Furto de Equipamento Oficial', 'felony', 30, 7500, '#f9b115', 'Subtrair rádio, colete, algema, distintivo, equipamento tático ou outro material oficial pertencente a agente ou órgão público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8022', 'Roubo de Equipamento Oficial', 'felony', 45, 12500, '#f9b115', 'Subtrair equipamento oficial de agente público mediante violência ou grave ameaça.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8023', 'Furto de Viatura Oficial', 'felony', 45, 12500, '#f9b115', 'Subtrair veículo oficial sem emprego de violência ou grave ameaça.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8024', 'Roubo de Viatura Oficial', 'felony', 65, 20000, '#f9b115', 'Subtrair veículo oficial mediante violência, grave ameaça ou domínio sobre agente público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8025', 'Dano a Viatura Oficial', 'felony', 25, 7500, '#f9b115', 'Danificar, destruir ou inutilizar deliberadamente veículo oficial pertencente a órgão público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8026', 'Dano a Equipamento de Agente Público', 'felony', 20, 5000, '#f9b115', 'Danificar ou inutilizar deliberadamente equipamento utilizado por agente público no exercício de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8027', 'Retenção Indevida de Equipamento Oficial', 'felony', 20, 5000, '#f9b115', 'Manter, esconder ou recusar devolução de equipamento oficial sabendo não possuir autorização para sua posse.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8028', 'Uso Indevido de Equipamento Oficial', 'felony', 25, 7500, '#f9b115', 'Utilizar sem autorização equipamento pertencente a agente ou órgão público de modo capaz de induzir terceiros em erro ou interferir em serviço oficial.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8029', 'Falsa Identificação como Agente Público', 'felony', 30, 7500, '#f9b115', 'Apresentar-se falsamente como agente público com objetivo de exercer autoridade, obter acesso ou conseguir vantagem indevida.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8030', 'Uso Fraudulento de Distintivo ou Credencial Oficial', 'felony', 30, 7500, '#f9b115', 'Utilizar distintivo, identificação ou credencial oficial falsa, furtada ou pertencente a terceiro para obter vantagem ou acesso indevido.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8031', 'Obstrução de Operação Policial', 'felony', 30, 7500, '#f9b115', 'Interferir deliberadamente em operação policial de forma capaz de atrasar, impedir ou comprometer sua execução.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8032', 'Interferência em Prisão de Terceiro', 'felony', 25, 6000, '#f9b115', 'Interferir deliberadamente para impedir ou dificultar prisão legítima de outra pessoa.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8033', 'Auxílio à Fuga de Pessoa Detida', 'felony', 35, 10000, '#f9b115', 'Auxiliar conscientemente pessoa detida ou presa a escapar da custódia de agente público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8034', 'Resgate de Preso', 'felony', 55, 17500, '#f9b115', 'Utilizar força, ameaça ou ação coordenada para retirar pessoa da custódia legítima de agentes públicos.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8035', 'Invasão de Área de Operação Policial', 'felony', 20, 5000, '#f9b115', 'Ingressar deliberadamente em área oficialmente isolada para operação policial sem autorização, comprometendo a segurança ou atuação dos agentes.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8036', 'Rompimento de Cerco Policial', 'felony', 35, 10000, '#f9b115', 'Romper deliberadamente bloqueio, cerco ou perímetro policial estabelecido para captura, segurança ou controle operacional.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8037', 'Uso de Veículo contra Agente Público', 'felony', 55, 17500, '#f9b115', 'Utilizar deliberadamente veículo para atingir, prensar, derrubar, ameaçar ou colocar agente público em grave risco físico.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8038', 'Disparo de Arma contra Agente Público', 'felony', 80, 25000, '#f9b115', 'Efetuar deliberadamente disparo de arma de fogo na direção de agente público durante ou em razão de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8039', 'Tentativa de Homicídio de Agente Público', 'felony', 110, 40000, '#f9b115', 'Praticar ato diretamente destinado a causar a morte de agente público, não ocorrendo o resultado por circunstância alheia à vontade do autor.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8040', 'Homicídio de Agente Público', 'felony', 120, 60000, '#f9b115', 'Causar deliberadamente a morte de agente público durante ou em razão do exercício de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8041', 'Tentativa de Homicídio de Agente Público mediante Emboscada', 'felony', 120, 50000, '#f9b115', 'Tentar matar agente público utilizando emboscada, surpresa ou recurso destinado a dificultar sua defesa.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8042', 'Homicídio de Agente Público mediante Emboscada', 'felony', 120, 75000, '#f9b115', 'Causar deliberadamente a morte de agente público mediante emboscada, tocaia ou recurso destinado a dificultar sua defesa.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8043', 'Contratação para Homicídio de Agente Público', 'felony', 120, 75000, '#f9b115', 'Contratar, pagar, oferecer recompensa ou solicitar a terceiro a morte de agente público em razão de sua função.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8044', 'Participação em Homicídio de Agente Público', 'felony', 110, 50000, '#f9b115', 'Auxiliar, facilitar, incentivar ou participar conscientemente da execução de homicídio contra agente público.', 'Crimes contra Agentes Públicos'),
('C.A.P. 8045', 'Sequestro de Agente Público', 'felony', 80, 25000, '#f9b115', 'Privar deliberadamente agente público de sua liberdade mediante força, ameaça, fraude ou retenção contra sua vontade.', 'Crimes contra Agentes Públicos');
INSERT INTO `mdt_penal_codes` (`code`, `label`, `charge_class`, `months`, `fine`, `color`, `description`, `category`) VALUES
