('C.O.P. 2032', 'Vandalismo', 'misdemeanor', 10, 2000, '#f91521', 'Danificar, quebrar, pichar ou deteriorar deliberadamente patrimônio pertencente a terceiro.', 'Civil e Ordem Pública'),
('C.O.P. 2033', 'Dano ao Patrimônio Público', 'felony', 20, 5000, '#f9b115', 'Danificar deliberadamente prédio, veículo, equipamento, mobiliário ou outro patrimônio pertencente ao poder público.', 'Civil e Ordem Pública'),
('C.O.P. 2034', 'Dano a Equipamento de Emergência', 'felony', 25, 7500, '#f9b115', 'Danificar, inutilizar ou interferir deliberadamente em equipamento destinado à segurança ou atendimento de emergência.', 'Civil e Ordem Pública'),
('C.O.P. 2035', 'Descarte Irregular de Resíduos', 'infraction', 0, 500, '#15f943', 'Descartar lixo, resíduos ou materiais em via pública ou local não autorizado.', 'Civil e Ordem Pública'),
('C.O.P. 2036', 'Queima Irregular em Área Pública', 'infraction', 0, 750, '#15f943', 'Realizar fogueira ou queima não autorizada em área pública ou urbana.', 'Civil e Ordem Pública'),
('C.O.P. 2037', 'Lançamento Perigoso de Objetos', 'misdemeanor', 5, 1000, '#f91521', 'Lançar objeto em via ou espaço público de maneira capaz de causar dano, acidente ou risco a terceiros.', 'Civil e Ordem Pública'),
('C.O.P. 2038', 'Embriaguez com Perturbação Pública', 'misdemeanor', 5, 1000, '#f91521', 'Encontrar-se sob efeito de álcool em espaço público e, em razão disso, provocar desordem, risco ou perturbação relevante.', 'Civil e Ordem Pública'),
('C.O.P. 2039', 'Consumo de Álcool em Local Proibido', 'infraction', 0, 500, '#15f943', 'Consumir bebida alcoólica em local onde seu consumo esteja expressamente proibido pelas normas da cidade.', 'Civil e Ordem Pública'),
('C.O.P. 2040', 'Comportamento Agressivo em Público', 'misdemeanor', 7, 1500, '#f91521', 'Adotar comportamento deliberadamente hostil ou agressivo capaz de causar temor ou perturbação relevante a terceiros.', 'Civil e Ordem Pública'),
('C.O.P. 2041', 'Intimidação', 'misdemeanor', 10, 2000, '#f91521', 'Intimidar deliberadamente outra pessoa mediante comportamento, palavras ou ações capazes de gerar temor razoável.', 'Civil e Ordem Pública'),
('C.O.P. 2042', 'Ameaça', 'felony', 15, 3000, '#f9b115', 'Ameaçar pessoa de causar mal injusto e relevante de maneira capaz de produzir temor razoável.', 'Civil e Ordem Pública'),
('C.O.P. 2043', 'Coação', 'felony', 20, 5000, '#f9b115', 'Constranger pessoa mediante ameaça, intimidação ou violência a fazer, deixar de fazer ou tolerar algo contra sua vontade.', 'Civil e Ordem Pública'),
('C.O.P. 2044', 'Perseguição Insistente', 'felony', 20, 4000, '#f9b115', 'Perseguir reiteradamente pessoa, restringindo sua liberdade ou causando temor por sua segurança.', 'Civil e Ordem Pública'),
('C.O.P. 2045', 'Assédio ou Importunação Persistente', 'misdemeanor', 10, 2000, '#f91521', 'Importunar, seguir ou abordar reiteradamente pessoa após manifestação clara de que a conduta é indesejada.', 'Civil e Ordem Pública');
INSERT INTO `mdt_penal_codes` (`code`, `label`, `charge_class`, `months`, `fine`, `color`, `description`, `category`) VALUES
('C.O.P. 2046', 'Solicitação Agressiva de Dinheiro ou Bens', 'misdemeanor', 5, 1000, '#f91521', 'Solicitar dinheiro, bens ou vantagem utilizando intimidação, perseguição, ameaça ou impedimento da passagem.', 'Civil e Ordem Pública'),
('C.O.P. 2047', 'Fraude na Solicitação de Doações', 'felony', 15, 5000, '#f9b115', 'Utilizar história, identidade, instituição ou finalidade deliberadamente falsa para induzir terceiros a realizar doação ou entregar valores.', 'Civil e Ordem Pública'),
('C.O.P. 2048', 'Obtenção de Serviço Mediante Fraude', 'felony', 15, 5000, '#f9b115', 'Obter serviço, acesso ou benefício mediante fraude, falsa identidade ou outro meio enganoso com intenção de não cumprir a obrigação correspondente.', 'Civil e Ordem Pública'),
('C.O.P. 2049', 'Apropriação de Bem Encontrado', 'misdemeanor', 7, 1500, '#f91521', 'Apropriar-se deliberadamente de bem encontrado pertencente a terceiro sem adotar medida razoável para devolução quando seu proprietário puder ser identificado.', 'Civil e Ordem Pública'),
('C.O.P. 2050', 'Subtração de Bem em Situação de Desordem', 'felony', 20, 5000, '#f9b115', 'Subtrair bem pertencente a terceiro aproveitando-se de tumulto, emergência, acidente ou situação de desordem pública.', 'Civil e Ordem Pública'),
('D.C. 9001', 'Desrespeito à Comunidade', 'infraction', 0, 0, '#15f943', 'Adotar comportamento desrespeitoso, hostil ou provocativo contra membros da comunidade sem configurar infração de maior gravidade.', 'Discord e Comunidade'),
('D.C. 9002', 'Ofensas Pessoais', 'misdemeanor', 0, 0, '#f91521', 'Dirigir insultos, humilhações ou ataques pessoais contra outro membro da comunidade.', 'Discord e Comunidade'),
('D.C. 9003', 'Assédio Persistente', 'felony', 0, 0, '#f9b115', 'Perseguir, importunar ou assediar reiteradamente outro membro por Discord, FiveM ou qualquer meio relacionado à comunidade.', 'Discord e Comunidade'),
('D.C. 9004', 'Discriminação', 'felony', 0, 0, '#f9b115', 'Praticar tratamento ofensivo ou discriminatório contra pessoa ou grupo com base em característica pessoal protegida ou identidade.', 'Discord e Comunidade'),
('D.C. 9005', 'Discurso de Ódio', 'felony', 0, 0, '#f9b115', 'Promover, incentivar ou divulgar discurso de ódio, hostilidade ou desumanização contra pessoa ou grupo.', 'Discord e Comunidade'),
('D.C. 9006', 'Ameaça Real contra Membro da Comunidade', 'felony', 0, 0, '#f9b115', 'Ameaçar causar dano real, físico, patrimonial ou pessoal a integrante da comunidade fora do contexto legítimo de roleplay.', 'Discord e Comunidade'),
('D.C. 9007', 'Incitação à Violência Real', 'felony', 0, 0, '#f9b115', 'Incentivar terceiros a praticar violência real contra jogador, membro da equipe ou integrante da comunidade.', 'Discord e Comunidade'),
('D.C. 9008', 'Humilhação Pública Organizada', 'felony', 0, 0, '#f9b115', 'Organizar ou incentivar campanha destinada a humilhar, ridicularizar ou constranger publicamente outro membro.', 'Discord e Comunidade'),
('D.C. 9009', 'Perseguição entre Plataformas', 'felony', 0, 0, '#f9b115', 'Perseguir deliberadamente membro da comunidade por Discord, redes sociais, FiveM ou outros meios após bloqueio ou pedido para cessar contato.', 'Discord e Comunidade'),
('D.C. 9010', 'Provocação Excessiva ou Flame', 'misdemeanor', 0, 0, '#f91521', 'Provocar conflitos, discussões ou hostilidade de maneira deliberada e repetitiva nos canais da comunidade.', 'Discord e Comunidade'),
('D.C. 9011', 'Spam', 'infraction', 0, 0, '#15f943', 'Enviar mensagens, imagens, comandos, marcações ou conteúdo repetitivo de maneira excessiva.', 'Discord e Comunidade'),
('D.C. 9012', 'Flood', 'infraction', 0, 0, '#15f943', 'Enviar grande quantidade de mensagens em curto período prejudicando a utilização normal dos canais.', 'Discord e Comunidade'),
('D.C. 9013', 'Uso Indevido de Menções', 'infraction', 0, 0, '#15f943', 'Utilizar menções de usuários, cargos ou grupos de forma abusiva ou sem necessidade.', 'Discord e Comunidade'),
('D.C. 9014', 'Divulgação em Canal Indevido', 'infraction', 0, 0, '#15f943', 'Publicar conteúdo promocional, convite ou anúncio em local não autorizado.', 'Discord e Comunidade'),
('D.C. 9015', 'Publicidade Não Autorizada', 'misdemeanor', 0, 0, '#f91521', 'Divulgar servidor, comunidade, produto, serviço ou conteúdo externo sem autorização da administração.', 'Discord e Comunidade'),
('D.C. 9016', 'Divulgação de Servidor Concorrente', 'felony', 0, 0, '#f9b115', 'Promover deliberadamente servidor ou comunidade concorrente utilizando os canais, jogadores ou estrutura da comunidade.', 'Discord e Comunidade'),
('D.C. 9017', 'Recrutamento Indevido de Membros', 'felony', 0, 0, '#f9b115', 'Tentar retirar membros da comunidade para grupo, servidor ou projeto externo mediante abordagem deliberada e não autorizada.', 'Discord e Comunidade'),
('D.C. 9018', 'Conteúdo Inadequado', 'misdemeanor', 0, 0, '#f91521', 'Publicar conteúdo inadequado, ofensivo ou incompatível com as regras e finalidade dos canais.', 'Discord e Comunidade'),
('D.C. 9019', 'Conteúdo Sexual Explícito', 'felony', 0, 0, '#f9b115', 'Publicar ou distribuir conteúdo sexual explícito em qualquer ambiente oficial da comunidade.', 'Discord e Comunidade'),
('D.C. 9020', 'Conteúdo Extremamente Gráfico', 'felony', 0, 0, '#f9b115', 'Publicar conteúdo real de violência extrema, mutilação ou material gráfico perturbador sem autorização e contexto adequado.', 'Discord e Comunidade'),
('D.C. 9021', 'Divulgação de Informação Pessoal', 'felony', 0, 0, '#f9b115', 'Divulgar sem consentimento informações pessoais ou privadas de outro membro da comunidade.', 'Discord e Comunidade'),
('D.C. 9022', 'Doxxing', 'felony', 0, 0, '#f9b115', 'Coletar, expor ou divulgar informações destinadas a identificar ou localizar pessoa no mundo real sem autorização.', 'Discord e Comunidade'),
('D.C. 9023', 'Ameaça de Doxxing', 'felony', 0, 0, '#f9b115', 'Ameaçar divulgar dados pessoais, localização ou informações privadas de membro da comunidade.', 'Discord e Comunidade'),
('D.C. 9024', 'Divulgação de Conversa Privada', 'misdemeanor', 0, 0, '#f91521', 'Publicar conversa privada sem autorização quando isso violar expectativa razoável de privacidade ou normas da comunidade.', 'Discord e Comunidade'),
('D.C. 9025', 'Vazamento de Conteúdo Interno', 'felony', 0, 0, '#f9b115', 'Divulgar sem autorização documentos, canais, informações ou conteúdo interno restrito da comunidade.', 'Discord e Comunidade'),
('D.C. 9026', 'Vazamento de Informação da Staff', 'felony', 0, 0, '#f9b115', 'Divulgar deliberadamente informações internas, investigações, decisões ou procedimentos reservados da equipe administrativa.', 'Discord e Comunidade'),
('D.C. 9027', 'Compartilhamento Indevido de Logs', 'felony', 0, 0, '#f9b115', 'Divulgar logs administrativos, registros internos ou informações de auditoria sem autorização.', 'Discord e Comunidade'),
('D.C. 9028', 'Gravação Indevida de Atendimento Privado', 'misdemeanor', 0, 0, '#f91521', 'Gravar ou divulgar atendimento privado da equipe em desacordo com as regras da comunidade.', 'Discord e Comunidade'),
('D.C. 9029', 'Falsa Identidade no Discord', 'misdemeanor', 0, 0, '#f91521', 'Utilizar identidade falsa com objetivo de enganar membros da comunidade sem configurar golpe patrimonial.', 'Discord e Comunidade'),
('D.C. 9030', 'Falsificação de Identidade de Staff', 'felony', 0, 0, '#f9b115', 'Fingir ser administrador, moderador ou integrante da equipe para exercer autoridade ou enganar outros membros.', 'Discord e Comunidade'),
('D.C. 9031', 'Uso Indevido do Nome da Administração', 'felony', 0, 0, '#f9b115', 'Alegar falsamente autorização, apoio ou decisão da administração para obter benefício ou influenciar terceiros.', 'Discord e Comunidade'),
('D.C. 9032', 'Falsificação de Prova contra Jogador', 'felony', 0, 0, '#f9b115', 'Criar, editar ou manipular imagem, vídeo, áudio, mensagem ou registro com objetivo de incriminar falsamente outro jogador.', 'Discord e Comunidade'),
('D.C. 9033', 'Manipulação de Evidência Administrativa', 'felony', 0, 0, '#f9b115', 'Alterar ou omitir deliberadamente evidência apresentada em denúncia, recurso ou investigação administrativa.', 'Discord e Comunidade'),
('D.C. 9034', 'Falsa Denúncia', 'felony', 0, 0, '#f9b115', 'Realizar denúncia sabendo que os fatos relatados são falsos com intenção de prejudicar outro membro.', 'Discord e Comunidade'),
('D.C. 9035', 'Abuso do Sistema de Tickets', 'misdemeanor', 0, 0, '#f91521', 'Abrir tickets repetitivos, falsos, ofensivos ou sem finalidade legítima para prejudicar o atendimento da equipe.', 'Discord e Comunidade'),
('D.C. 9036', 'Fraude em Ticket Administrativo', 'felony', 0, 0, '#f9b115', 'Utilizar informações ou provas falsas em ticket com objetivo de obter vantagem, benefício ou punição indevida de terceiro.', 'Discord e Comunidade'),
('D.C. 9037', 'Tentativa de Enganar a Staff', 'felony', 0, 0, '#f9b115', 'Fornecer deliberadamente versão falsa, informação manipulada ou omissão relevante para enganar decisão administrativa.', 'Discord e Comunidade'),
('D.C. 9038', 'Fraude em Benefício ou Recompensa', 'felony', 0, 0, '#f9b115', 'Utilizar fraude, conta alternativa ou informação falsa para obter recompensa, benefício, item ou vantagem da comunidade.', 'Discord e Comunidade'),
('D.C. 9039', 'Golpe contra Jogador', 'felony', 0, 0, '#f9b115', 'Utilizar engano, fraude ou falsa promessa para obter dinheiro, item, conta, benefício ou vantagem de outro membro.', 'Discord e Comunidade'),
('D.C. 9040', 'Golpe envolvendo Dinheiro Real', 'felony', 0, 0, '#f9b115', 'Utilizar a comunidade para aplicar golpe envolvendo dinheiro real, pagamento, produto ou serviço.', 'Discord e Comunidade'),
('D.C. 9041', 'Fraude em Venda de Produto ou Serviço', 'felony', 0, 0, '#f9b115', 'Oferecer produto ou serviço utilizando informações falsas com objetivo de obter vantagem de integrante da comunidade.', 'Discord e Comunidade'),
('D.C. 9042', 'Phishing contra Membros', 'felony', 0, 0, '#f9b115', 'Tentar obter senha, token, credencial ou informação de acesso de membro mediante página, mensagem ou identidade fraudulenta.', 'Discord e Comunidade'),
('D.C. 9043', 'Roubo ou Apropriação de Conta', 'felony', 0, 0, '#f9b115', 'Obter, assumir ou manter acesso não autorizado à conta de outro membro da comunidade.', 'Discord e Comunidade'),
('D.C. 9044', 'Subtração de Bens Digitais', 'felony', 0, 0, '#f9b115', 'Subtrair ou transferir sem autorização itens, valores ou ativos digitais pertencentes a outro jogador.', 'Discord e Comunidade'),
('D.C. 9045', 'Comércio Externo Não Autorizado', 'felony', 0, 0, '#f9b115', 'Comprar, vender ou negociar por dinheiro real itens, veículos, personagens, moeda ou vantagens do servidor sem autorização.', 'Discord e Comunidade'),
('D.C. 9046', 'Venda de Conta', 'felony', 0, 0, '#f9b115', 'Vender, comprar ou negociar conta vinculada ao servidor ou comunidade em desacordo com as regras estabelecidas.', 'Discord e Comunidade'),
('D.C. 9047', 'Compartilhamento Indevido de Conta', 'felony', 0, 0, '#f9b115', 'Compartilhar acesso à conta com terceiros quando tal conduta comprometer segurança, punições ou integridade do servidor.', 'Discord e Comunidade'),
('D.C. 9048', 'Evasão de Punição', 'felony', 0, 0, '#f9b115', 'Utilizar outra conta, identidade ou meio técnico para evitar mute, suspensão, banimento ou outra punição administrativa.', 'Discord e Comunidade'),
('D.C. 9049', 'Ban Evasion', 'felony', 0, 0, '#f9b115', 'Retornar deliberadamente à comunidade utilizando conta alternativa ou outro meio após banimento ativo.', 'Discord e Comunidade'),
('D.C. 9050', 'Auxílio à Evasão de Banimento', 'felony', 0, 0, '#f9b115', 'Auxiliar conscientemente pessoa banida a retornar ou ocultar sua identidade dentro da comunidade.', 'Discord e Comunidade'),
('D.C. 9051', 'Metagaming por Discord', 'felony', 0, 0, '#f9b115', 'Utilizar informações obtidas fora do personagem, inclusive por Discord, transmissão ou mensagem privada, para obter vantagem dentro do roleplay.', 'Discord e Comunidade'),
('D.C. 9052', 'Compartilhamento de Informação IC por Meio OOC', 'felony', 0, 0, '#f9b115', 'Transmitir por meio externo informação de personagem que não poderia legitimamente ser conhecida pelo destinatário dentro do roleplay.', 'Discord e Comunidade'),
('D.C. 9053', 'Ghosting por Stream', 'felony', 0, 0, '#f9b115', 'Assistir transmissão de outro jogador com objetivo de obter posição, estratégia ou informação para utilização dentro do servidor.', 'Discord e Comunidade'),
('D.C. 9054', 'Stream Sniping', 'felony', 0, 0, '#f9b115', 'Utilizar transmissão ao vivo para localizar, perseguir, abordar ou interferir deliberadamente com outro jogador dentro do servidor.', 'Discord e Comunidade'),
('D.C. 9055', 'Coordenação OOC para Obter Vantagem IC', 'felony', 0, 0, '#f9b115', 'Coordenar ações fora do personagem para produzir vantagem indevida dentro do roleplay.', 'Discord e Comunidade'),
('D.C. 9056', 'Divulgação de Informação Sigilosa do RP', 'felony', 0, 0, '#f9b115', 'Compartilhar externamente informação sigilosa obtida em contexto de roleplay quando isso comprometer investigação, operação ou narrativa em andamento.', 'Discord e Comunidade'),
('D.C. 9057', 'Exploração de Bug para Obter Vantagem', 'felony', 0, 0, '#f9b115', 'Explorar deliberadamente falha do servidor, sistema ou interface para obter vantagem, item, dinheiro ou benefício indevido.', 'Discord e Comunidade'),
('D.C. 9058', 'Omissão Deliberada de Bug Explorado', 'felony', 0, 0, '#f9b115', 'Continuar explorando vulnerabilidade conhecida sem comunicar a equipe quando dela resultar vantagem relevante ou prejuízo à comunidade.', 'Discord e Comunidade'),
('D.C. 9059', 'Divulgação Maliciosa de Exploit', 'felony', 0, 0, '#f9b115', 'Divulgar vulnerabilidade, exploit ou método de abuso com objetivo de permitir sua exploração por outros membros.', 'Discord e Comunidade'),
('D.C. 9060', 'Ataque Coordenado contra a Comunidade', 'felony', 0, 0, '#f9b115', 'Organizar ou participar de ação coordenada destinada a prejudicar gravemente o servidor, Discord, equipe ou comunidade, incluindo sabotagem, raids ou abuso massivo de sistemas.', 'Discord e Comunidade'),
('D.S.I. 6001', 'Posse de Pequena Quantidade de Substância Ilícita', 'misdemeanor', 5, 1500, '#f91521', 'Possuir pequena quantidade de substância ilícita destinada aparentemente a consumo pessoal, sem indício de comercialização.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6002', 'Posse de Substância Ilícita', 'felony', 10, 3000, '#f9b115', 'Possuir quantidade relevante de substância ilícita sem autorização ou justificativa legítima.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6003', 'Posse de Múltiplas Substâncias Ilícitas', 'felony', 15, 4000, '#f9b115', 'Possuir simultaneamente duas ou mais substâncias ilícitas distintas em quantidade relevante.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6004', 'Posse de Substância Ilícita em Área Pública', 'misdemeanor', 7, 2000, '#f91521', 'Portar ou manter substância ilícita em praça, rua, estabelecimento ou outro local de acesso público.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6005', 'Posse de Substância Ilícita em Área Restrita', 'felony', 20, 5000, '#f9b115', 'Portar substância ilícita em instalação policial, governamental, hospitalar ou outra área oficialmente restrita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6006', 'Posse de Grande Quantidade de Substância Ilícita', 'felony', 35, 10000, '#f9b115', 'Possuir quantidade elevada de substância ilícita incompatível com simples consumo pessoal.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6007', 'Consumo de Substância Ilícita em Via Pública', 'misdemeanor', 5, 1500, '#f91521', 'Consumir substância ilícita em via pública ou local de acesso coletivo.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6008', 'Consumo de Substância Ilícita em Área Restrita', 'felony', 15, 4000, '#f9b115', 'Consumir substância ilícita em instalação ou área onde sua presença represente risco adicional à segurança.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6009', 'Consumo de Substância Ilícita Durante Atividade Profissional de Risco', 'felony', 20, 5000, '#f9b115', 'Consumir ou permanecer sob efeito de substância ilícita durante atividade profissional capaz de colocar terceiros em risco.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6010', 'Posse de Substância Ilícita para Distribuição', 'felony', 35, 10000, '#f9b115', 'Possuir substância ilícita em circunstâncias compatíveis com intenção de distribuição, entrega ou comercialização.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6011', 'Venda de Substância Ilícita', 'felony', 50, 15000, '#f9b115', 'Vender ou comercializar substância ilícita a outra pessoa.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6012', 'Distribuição de Substância Ilícita', 'felony', 45, 12500, '#f9b115', 'Distribuir, fornecer ou entregar substância ilícita, ainda que sem recebimento direto de pagamento.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6013', 'Tráfico de Drogas', 'felony', 70, 25000, '#f9b115', 'Participar de atividade organizada ou habitual de comercialização, distribuição ou fornecimento de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6014', 'Tráfico de Drogas em Grande Escala', 'felony', 100, 40000, '#f9b115', 'Participar de operação de tráfico envolvendo grande quantidade, estrutura organizada ou ampla distribuição de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6015', 'Tráfico de Múltiplas Substâncias', 'felony', 90, 35000, '#f9b115', 'Comercializar ou distribuir de forma organizada diferentes tipos de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6016', 'Transporte de Substância Ilícita', 'felony', 35, 10000, '#f9b115', 'Transportar conscientemente substância ilícita para terceiro, grupo ou atividade criminosa.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6017', 'Transporte de Grande Quantidade de Drogas', 'felony', 60, 20000, '#f9b115', 'Transportar conscientemente grande quantidade de substância ilícita destinada à distribuição ou comercialização.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6018', 'Ocultação de Substância Ilícita', 'felony', 25, 7500, '#f9b115', 'Ocultar deliberadamente substância ilícita com objetivo de impedir sua localização, apreensão ou identificação.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6019', 'Armazenamento de Drogas para Terceiros', 'felony', 35, 10000, '#f9b115', 'Guardar conscientemente substâncias ilícitas pertencentes a terceiro ou organização criminosa.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6020', 'Manutenção de Depósito de Substâncias Ilícitas', 'felony', 55, 17500, '#f9b115', 'Manter imóvel ou local destinado ao armazenamento relevante de substâncias ilícitas para distribuição.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6021', 'Fornecimento de Local para Tráfico', 'felony', 40, 12500, '#f9b115', 'Disponibilizar conscientemente imóvel, estabelecimento ou propriedade para comercialização ou distribuição de drogas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6022', 'Financiamento de Atividade de Tráfico', 'felony', 70, 25000, '#f9b115', 'Fornecer dinheiro ou recursos conscientemente destinados à manutenção ou expansão de atividade de tráfico de drogas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6023', 'Administração de Atividade de Tráfico', 'felony', 80, 30000, '#f9b115', 'Coordenar, dirigir, organizar ou administrar conscientemente atividade destinada ao tráfico de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6024', 'Intermediação de Venda de Drogas', 'felony', 35, 10000, '#f9b115', 'Intermediar contato, negociação, pagamento ou entrega entre fornecedor e comprador de substância ilícita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6025', 'Tentativa de Venda de Substância Ilícita', 'felony', 30, 7500, '#f9b115', 'Iniciar negociação ou ato diretamente destinado à comercialização de droga sem que a venda seja concluída.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6026', 'Oferta de Substância Ilícita', 'misdemeanor', 10, 3000, '#f91521', 'Oferecer substância ilícita a outra pessoa, ainda que a entrega ou venda não se concretize.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6027', 'Indução ao Consumo de Substância Ilícita', 'felony', 20, 5000, '#f9b115', 'Induzir, pressionar ou incentivar deliberadamente outra pessoa a consumir substância ilícita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6028', 'Fornecimento de Droga sem Consentimento', 'felony', 50, 15000, '#f9b115', 'Administrar ou fornecer substância ilícita a pessoa sem seu conhecimento ou consentimento.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6029', 'Administração de Substância com Intenção de Incapacitar', 'felony', 65, 20000, '#f9b115', 'Administrar deliberadamente substância a outra pessoa com objetivo de reduzir sua capacidade de reação, consciência ou resistência.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6030', 'Administração de Substância com Intenção de Matar', 'felony', 100, 35000, '#f9b115', 'Administrar deliberadamente substância tóxica ou ilícita a outra pessoa com intenção direta de causar sua morte.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6031', 'Morte Causada por Administração Intencional de Substância', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa mediante administração de substância tóxica, ilícita ou adulterada.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6032', 'Venda de Substância Adulterada como Droga', 'felony', 40, 12500, '#f9b115', 'Vender substância adulterada, falsa ou diferente daquela anunciada com objetivo de obter vantagem econômica ilícita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6033', 'Fraude na Comercialização de Substância', 'felony', 35, 10000, '#f9b115', 'Utilizar engano, falsa identidade, falsa quantidade ou informação fraudulenta para obter vantagem em negociação envolvendo substância ilícita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6034', 'Venda Fictícia de Substância Ilícita', 'felony', 30, 7500, '#f9b115', 'Receber dinheiro ou vantagem prometendo entregar substância ilícita inexistente ou que não pretende fornecer.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6035', 'Falsificação de Receita ou Autorização Médica', 'felony', 30, 7500, '#f9b115', 'Criar, alterar ou utilizar documento médico falso para obter medicamento ou substância controlada.', 'Drogas e Substâncias Ilícitas');
INSERT INTO `mdt_penal_codes` (`code`, `label`, `charge_class`, `months`, `fine`, `color`, `description`, `category`) VALUES
('D.S.I. 6036', 'Uso Fraudulento de Receita de Terceiro', 'felony', 25, 6000, '#f9b115', 'Utilizar receita, autorização ou documento médico pertencente a terceiro para obter substância controlada.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6037', 'Obtenção Fraudulenta de Medicamento Controlado', 'felony', 30, 7500, '#f9b115', 'Obter medicamento controlado mediante declaração falsa, documento fraudulento ou outro meio enganoso.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6038', 'Posse Ilegal de Medicamento Controlado', 'misdemeanor', 8, 2000, '#f91521', 'Possuir medicamento ou substância controlada sem prescrição, autorização ou justificativa legítima exigida.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6039', 'Venda Ilegal de Medicamento Controlado', 'felony', 40, 12500, '#f9b115', 'Vender ou fornecer medicamento controlado sem autorização legal.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6040', 'Desvio de Medicamento Controlado', 'felony', 35, 10000, '#f9b115', 'Desviar medicamento controlado pertencente a hospital, farmácia, serviço médico ou terceiro para uso ou distribuição ilícita.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6041', 'Furto de Medicamento Controlado', 'felony', 30, 7500, '#f9b115', 'Subtrair medicamento ou substância controlada pertencente a hospital, farmácia, serviço médico ou terceiro.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6042', 'Roubo de Medicamento Controlado', 'felony', 50, 15000, '#f9b115', 'Subtrair medicamento ou substância controlada mediante violência, ameaça ou intimidação.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6043', 'Furto de Substância Ilícita', 'felony', 25, 6000, '#f9b115', 'Subtrair substância ilícita pertencente a terceiro sem emprego de violência ou grave ameaça.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6044', 'Roubo de Substância Ilícita', 'felony', 45, 12500, '#f9b115', 'Subtrair substância ilícita pertencente a terceiro mediante violência, ameaça ou intimidação.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6045', 'Receptação de Substância Ilícita Roubada ou Furtada', 'felony', 30, 7500, '#f9b115', 'Receber, guardar, transportar ou ocultar substância ilícita sabendo que foi obtida mediante roubo ou furto.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6046', 'Destruição ou Ocultação de Drogas para Evitar Apreensão', 'felony', 25, 7500, '#f9b115', 'Destruir, descartar ou ocultar deliberadamente substância ilícita com objetivo de impedir sua apreensão durante fiscalização ou investigação.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6047', 'Fornecimento de Informação Falsa sobre Origem de Substância', 'felony', 20, 5000, '#f9b115', 'Fornecer deliberadamente informação falsa sobre procedência, propriedade ou destino de substância ilícita para impedir responsabilização.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6048', 'Uso de Terceiro para Transporte de Drogas', 'felony', 50, 15000, '#f9b115', 'Utilizar conscientemente outra pessoa para transportar substância ilícita destinada à distribuição ou atividade criminosa.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6049', 'Participação em Organização de Tráfico', 'felony', 85, 30000, '#f9b115', 'Integrar conscientemente grupo estruturado destinado à produção, transporte, armazenamento, distribuição ou comercialização de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('D.S.I. 6050', 'Comando de Organização de Tráfico', 'felony', 120, 50000, '#f9b115', 'Liderar, comandar ou exercer função de direção em organização destinada ao tráfico de substâncias ilícitas.', 'Drogas e Substâncias Ilícitas'),
('P.C. 3001', 'Agressão Simples', 'misdemeanor', 7, 1500, '#f91521', 'Agredir fisicamente outra pessoa causando lesão de pequena gravidade, sem emprego de arma ou circunstância agravante.', 'Crimes Penais'),
('P.C. 3002', 'Lesão Corporal', 'felony', 15, 3000, '#f9b115', 'Ofender deliberadamente a integridade corporal ou a saúde de outra pessoa causando lesão relevante.', 'Crimes Penais'),
('P.C. 3003', 'Lesão Corporal Grave', 'felony', 30, 6000, '#f9b115', 'Causar deliberadamente lesão grave, incapacitante ou que represente risco significativo à vida da vítima.', 'Crimes Penais'),
('P.C. 3004', 'Lesão Corporal com Arma', 'felony', 35, 7500, '#f9b115', 'Agredir ou ferir outra pessoa utilizando arma de fogo, arma branca ou outro instrumento potencialmente letal.', 'Crimes Penais'),
('P.C. 3005', 'Agressão em Grupo', 'felony', 25, 5000, '#f9b115', 'Participar juntamente com duas ou mais pessoas de agressão deliberada contra uma vítima.', 'Crimes Penais'),
('P.C. 3006', 'Ameaça', 'misdemeanor', 10, 2000, '#f91521', 'Ameaçar outra pessoa de causar mal injusto e relevante de modo capaz de produzir temor razoável.', 'Crimes Penais'),
('P.C. 3007', 'Ameaça com Arma', 'felony', 20, 4000, '#f9b115', 'Ameaçar ou intimidar outra pessoa utilizando arma ou instrumento capaz de causar morte ou lesão grave.', 'Crimes Penais'),
('P.C. 3008', 'Intimidação Criminal', 'misdemeanor', 12, 2500, '#f91521', 'Utilizar ameaça, perseguição ou comportamento intimidatório para provocar temor ou constranger outra pessoa.', 'Crimes Penais'),
('P.C. 3009', 'Coação', 'felony', 20, 4000, '#f9b115', 'Constranger alguém mediante violência ou grave ameaça a realizar, deixar de realizar ou tolerar determinada conduta.', 'Crimes Penais'),
('P.C. 3010', 'Coação Mediante Arma', 'felony', 30, 6000, '#f9b115', 'Constranger outra pessoa mediante ameaça ou violência utilizando arma de fogo, arma branca ou instrumento equivalente.', 'Crimes Penais'),
('P.C. 3011', 'Perseguição', 'felony', 20, 3500, '#f9b115', 'Perseguir reiteradamente outra pessoa causando temor, restringindo sua liberdade ou perturbando gravemente sua privacidade.', 'Crimes Penais'),
('P.C. 3012', 'Sequestro', 'felony', 50, 10000, '#f9b115', 'Privar deliberadamente outra pessoa de sua liberdade mediante força, ameaça, fraude ou retenção contra sua vontade.', 'Crimes Penais'),
('P.C. 3013', 'Sequestro Agravado', 'felony', 80, 17500, '#f9b115', 'Praticar sequestro mediante uso de arma, violência grave, participação de múltiplos autores ou prolongada privação de liberdade.', 'Crimes Penais'),
('P.C. 3014', 'Cárcere Privado', 'felony', 40, 7500, '#f9b115', 'Manter pessoa confinada, presa ou impedida de deixar determinado local contra sua vontade.', 'Crimes Penais'),
('P.C. 3015', 'Tomada de Refém', 'felony', 90, 20000, '#f9b115', 'Manter pessoa sob domínio ou privação de liberdade com objetivo de exigir condição, vantagem ou impedir ação de terceiros.', 'Crimes Penais'),
('P.C. 3016', 'Tortura', 'felony', 90, 20000, '#f9b115', 'Submeter pessoa intencionalmente a sofrimento físico ou mental grave com finalidade de punição, intimidação, obtenção de informação ou confissão.', 'Crimes Penais'),
('P.C. 3017', 'Maus-Tratos', 'felony', 20, 3500, '#f9b115', 'Submeter pessoa sob responsabilidade, autoridade ou cuidado a tratamento cruel, abusivo ou incompatível com sua segurança.', 'Crimes Penais'),
('P.C. 3018', 'Abandono de Pessoa Vulnerável', 'felony', 25, 5000, '#f9b115', 'Abandonar pessoa que esteja sob responsabilidade do agente e que não possua condições adequadas de proteger-se dos riscos decorrentes do abandono.', 'Crimes Penais'),
('P.C. 3019', 'Omissão de Socorro', 'misdemeanor', 10, 2000, '#f91521', 'Deixar injustificadamente de prestar ou solicitar auxílio possível a pessoa em situação evidente de grave perigo.', 'Crimes Penais'),
('P.C. 3020', 'Exposição da Vida de Terceiro a Perigo', 'felony', 20, 4000, '#f9b115', 'Praticar deliberadamente conduta que exponha outra pessoa a risco concreto e relevante de morte ou lesão grave.', 'Crimes Penais'),
('P.C. 3021', 'Incitação à Violência', 'felony', 20, 4000, '#f9b115', 'Incentivar deliberadamente terceiros a praticar violência contra pessoa ou grupo determinado.', 'Crimes Penais'),
('P.C. 3022', 'Participação em Briga Generalizada', 'misdemeanor', 10, 2000, '#f91521', 'Participar voluntariamente de confronto físico envolvendo diversas pessoas e capaz de causar lesões ou grave desordem.', 'Crimes Penais'),
('P.C. 3023', 'Incêndio Criminoso', 'felony', 45, 10000, '#f9b115', 'Provocar deliberadamente incêndio em imóvel, veículo ou estrutura colocando patrimônio ou pessoas em risco.', 'Crimes Penais'),
('P.C. 3024', 'Incêndio Criminoso com Risco à Vida', 'felony', 70, 15000, '#f9b115', 'Provocar deliberadamente incêndio em circunstâncias capazes de colocar diretamente uma ou mais pessoas em grave risco de morte.', 'Crimes Penais'),
('P.C. 3025', 'Explosão Criminosa', 'felony', 70, 17500, '#f9b115', 'Provocar deliberadamente explosão capaz de causar destruição relevante, lesões ou risco à vida de terceiros.', 'Crimes Penais'),
('P.C. 3026', 'Colocação Deliberada de Pessoa em Perigo', 'felony', 25, 5000, '#f9b115', 'Criar intencionalmente situação concreta de perigo grave para outra pessoa, ainda que não ocorra efetiva lesão.', 'Crimes Penais'),
('P.C. 3027', 'Envenenamento', 'felony', 60, 12500, '#f9b115', 'Administrar deliberadamente substância tóxica ou prejudicial a outra pessoa com intenção de causar dano à saúde.', 'Crimes Penais'),
('P.C. 3028', 'Envenenamento com Intenção de Matar', 'felony', 100, 25000, '#f9b115', 'Administrar deliberadamente substância tóxica ou letal a outra pessoa com intenção de provocar sua morte.', 'Crimes Penais'),
('P.C. 3029', 'Tentativa de Homicídio', 'felony', 90, 22500, '#f9b115', 'Praticar ato diretamente destinado a causar a morte de outra pessoa, não ocorrendo o resultado por circunstância alheia à vontade do agente.', 'Crimes Penais'),
('P.C. 3030', 'Tentativa de Homicídio Qualificado', 'felony', 110, 30000, '#f9b115', 'Tentar causar deliberadamente a morte de outra pessoa mediante circunstância especialmente grave, emboscada, crueldade ou outro meio qualificado.', 'Crimes Penais'),
('P.C. 3031', 'Homicídio Culposo', 'felony', 45, 10000, '#f9b115', 'Causar a morte de outra pessoa sem intenção de matar, em razão de imprudência, negligência ou imperícia relevante.', 'Crimes Penais'),
('P.C. 3032', 'Homicídio Doloso', 'felony', 100, 30000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa com intenção de matar ou assumindo conscientemente o risco do resultado.', 'Crimes Penais'),
('P.C. 3033', 'Homicídio Qualificado', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa mediante circunstância especialmente grave, crueldade, emboscada ou recurso que dificulte sua defesa.', 'Crimes Penais'),
('P.C. 3034', 'Homicídio por Motivo Torpe', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa motivado por pagamento, recompensa ou razão especialmente desprezível.', 'Crimes Penais'),
('P.C. 3035', 'Homicídio Mediante Emboscada', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa mediante emboscada, surpresa ou recurso destinado a impedir ou dificultar sua defesa.', 'Crimes Penais'),
('P.C. 3036', 'Homicídio Mediante Crueldade', 'felony', 120, 50000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa utilizando meio cruel ou capaz de provocar sofrimento desnecessário.', 'Crimes Penais'),
('P.C. 3037', 'Homicídio Múltiplo', 'felony', 120, 75000, '#f9b115', 'Causar deliberadamente a morte de duas ou mais pessoas durante o mesmo contexto criminoso.', 'Crimes Penais'),
('P.C. 3038', 'Participação em Homicídio', 'felony', 90, 25000, '#f9b115', 'Auxiliar, incentivar, facilitar ou participar conscientemente da execução de homicídio cometido por outra pessoa.', 'Crimes Penais'),
('P.C. 3039', 'Contratação de Homicídio', 'felony', 120, 75000, '#f9b115', 'Contratar, pagar, oferecer recompensa ou solicitar a terceiro a execução deliberada da morte de outra pessoa.', 'Crimes Penais'),
('P.C. 3040', 'Execução de Homicídio por Recompensa', 'felony', 120, 75000, '#f9b115', 'Causar deliberadamente a morte de outra pessoa em troca de dinheiro, benefício, recompensa ou promessa de vantagem.', 'Crimes Penais'),
('P.C. 3041', 'Ocultação de Pessoa Sequestrada', 'felony', 50, 10000, '#f9b115', 'Ocultar deliberadamente pessoa privada ilegalmente de liberdade ou auxiliar na manutenção de seu cativeiro.', 'Crimes Penais'),
('P.C. 3042', 'Auxílio a Sequestro', 'felony', 40, 7500, '#f9b115', 'Auxiliar conscientemente planejamento, execução, transporte, vigilância ou manutenção de pessoa sequestrada.', 'Crimes Penais'),
('P.C. 3043', 'Privação de Liberdade mediante Fraude', 'felony', 35, 7500, '#f9b115', 'Utilizar engano ou fraude para levar pessoa a situação em que seja posteriormente impedida de deixar determinado local.', 'Crimes Penais'),
('P.C. 3044', 'Administração de Substância sem Consentimento', 'felony', 25, 5000, '#f9b115', 'Administrar deliberadamente droga, medicamento ou outra substância capaz de alterar a consciência ou capacidade física de alguém sem seu consentimento.', 'Crimes Penais'),
('P.C. 3045', 'Violação Grave de Domicílio', 'felony', 20, 4000, '#f9b115', 'Invadir residência de terceiro mediante violência, ameaça, arrombamento ou com intenção de praticar outro crime.', 'Crimes Penais'),
('P.C. 3046', 'Confinamento mediante Ameaça', 'felony', 30, 6000, '#f9b115', 'Impedir pessoa de abandonar determinado local mediante ameaça grave, intimidação ou demonstração de força.', 'Crimes Penais'),
('P.C. 3047', 'Uso de Pessoa como Escudo Humano', 'felony', 80, 20000, '#f9b115', 'Utilizar pessoa contra sua vontade como proteção contra disparos, captura, intervenção policial ou ataque de terceiros.', 'Crimes Penais'),
('P.C. 3048', 'Colocação de Refém em Risco de Morte', 'felony', 100, 30000, '#f9b115', 'Expor deliberadamente pessoa mantida como refém a situação concreta e imediata de morte ou lesão gravíssima.', 'Crimes Penais'),
('P.C. 3049', 'Tentativa de Lesão Corporal Grave', 'felony', 20, 4000, '#f9b115', 'Praticar ato deliberadamente destinado a provocar lesão corporal grave, sem que o resultado se concretize.', 'Crimes Penais'),
('P.C. 3050', 'Participação em Agressão Criminosa', 'felony', 15, 3000, '#f9b115', 'Auxiliar, incentivar ou facilitar conscientemente agressão criminosa praticada por outra pessoa.', 'Crimes Penais'),
('PAT. 4001', 'Furto Simples', 'felony', 15, 3000, '#f9b115', 'Subtrair para si ou para terceiro bem móvel pertencente a outra pessoa, sem emprego de violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4002', 'Furto de Pequeno Valor', 'misdemeanor', 7, 1500, '#f91521', 'Subtrair bem móvel de pequeno valor pertencente a terceiro, sem emprego de violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4003', 'Furto Qualificado', 'felony', 25, 5000, '#f9b115', 'Praticar furto mediante arrombamento, destruição de obstáculo, fraude, abuso de confiança ou outro meio especialmente elaborado.', 'Crimes Patrimoniais'),
('PAT. 4004', 'Furto em Residência', 'felony', 30, 6000, '#f9b115', 'Subtrair bem pertencente a terceiro no interior de residência, apartamento ou propriedade utilizada como moradia.', 'Crimes Patrimoniais'),
('PAT. 4005', 'Furto em Estabelecimento Comercial', 'felony', 20, 4000, '#f9b115', 'Subtrair mercadoria, dinheiro ou outro bem pertencente a estabelecimento comercial sem emprego de violência.', 'Crimes Patrimoniais'),
('PAT. 4006', 'Furto de Veículo', 'felony', 35, 7500, '#f9b115', 'Subtrair veículo automotor pertencente a terceiro sem emprego de violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4007', 'Furto de Motocicleta', 'felony', 30, 6000, '#f9b115', 'Subtrair motocicleta pertencente a terceiro sem emprego de violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4008', 'Furto de Peças de Veículo', 'felony', 20, 4000, '#f9b115', 'Subtrair rodas, componentes, equipamentos ou outras peças instaladas em veículo pertencente a terceiro.', 'Crimes Patrimoniais'),
('PAT. 4009', 'Furto de Carga', 'felony', 35, 8000, '#f9b115', 'Subtrair mercadorias ou bens transportados como carga sem emprego direto de violência contra pessoa.', 'Crimes Patrimoniais'),
('PAT. 4010', 'Furto de Equipamento Público', 'felony', 30, 7500, '#f9b115', 'Subtrair equipamento, material ou bem pertencente a órgão ou serviço público.', 'Crimes Patrimoniais'),
('PAT. 4011', 'Furto mediante Abuso de Confiança', 'felony', 25, 5000, '#f9b115', 'Subtrair bem pertencente a terceiro aproveitando-se de relação de confiança, emprego, acesso autorizado ou responsabilidade concedida.', 'Crimes Patrimoniais'),
('PAT. 4012', 'Furto mediante Fraude', 'felony', 30, 6500, '#f9b115', 'Utilizar fraude ou artifício para possibilitar ou facilitar a subtração de bem pertencente a terceiro.', 'Crimes Patrimoniais'),
('PAT. 4013', 'Tentativa de Furto', 'misdemeanor', 10, 2000, '#f91521', 'Iniciar deliberadamente a subtração de bem pertencente a terceiro sem consumar o furto por circunstância alheia à vontade do agente.', 'Crimes Patrimoniais'),
('PAT. 4014', 'Roubo Simples', 'felony', 35, 7500, '#f9b115', 'Subtrair bem pertencente a outra pessoa mediante violência, ameaça ou intimidação.', 'Crimes Patrimoniais'),
('PAT. 4015', 'Roubo à Mão Armada', 'felony', 55, 12500, '#f9b115', 'Subtrair bem pertencente a terceiro mediante emprego ou exibição de arma para ameaçar ou dominar a vítima.', 'Crimes Patrimoniais'),
('PAT. 4016', 'Roubo com Violência', 'felony', 50, 10000, '#f9b115', 'Subtrair bem pertencente a terceiro utilizando violência física contra a vítima.', 'Crimes Patrimoniais'),
('PAT. 4017', 'Roubo em Residência', 'felony', 55, 12500, '#f9b115', 'Invadir ou permanecer em residência com objetivo de subtrair bens mediante violência ou grave ameaça aos ocupantes.', 'Crimes Patrimoniais'),
('PAT. 4018', 'Roubo a Estabelecimento Comercial', 'felony', 45, 10000, '#f9b115', 'Subtrair dinheiro, mercadorias ou outros bens de estabelecimento comercial mediante violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4019', 'Roubo de Veículo', 'felony', 55, 12500, '#f9b115', 'Subtrair veículo pertencente a terceiro mediante violência, ameaça ou intimidação contra seu proprietário ou ocupante.', 'Crimes Patrimoniais'),
('PAT. 4020', 'Roubo de Carga', 'felony', 60, 15000, '#f9b115', 'Subtrair carga ou mercadorias em transporte mediante violência, ameaça ou domínio sobre motorista ou responsáveis.', 'Crimes Patrimoniais'),
('PAT. 4021', 'Roubo a Caixa Eletrônico', 'felony', 55, 15000, '#f9b115', 'Subtrair ou tentar subtrair valores existentes em caixa eletrônico mediante rompimento, violência ou método criminoso equivalente.', 'Crimes Patrimoniais'),
('PAT. 4022', 'Roubo a Banco', 'felony', 80, 25000, '#f9b115', 'Subtrair valores, bens ou ativos pertencentes a instituição bancária mediante violência, ameaça ou ação criminosa organizada.', 'Crimes Patrimoniais'),
('PAT. 4023', 'Roubo de Valores em Transporte', 'felony', 70, 20000, '#f9b115', 'Subtrair dinheiro ou valores durante transporte, escolta ou movimentação mediante violência ou grave ameaça.', 'Crimes Patrimoniais'),
('PAT. 4024', 'Roubo em Grupo', 'felony', 60, 15000, '#f9b115', 'Praticar roubo com participação consciente de duas ou mais pessoas atuando conjuntamente.', 'Crimes Patrimoniais'),
('PAT. 4025', 'Tentativa de Roubo', 'felony', 30, 6000, '#f9b115', 'Iniciar execução de roubo mediante violência ou grave ameaça sem conseguir efetivar a subtração pretendida.', 'Crimes Patrimoniais'),
('PAT. 4026', 'Latrocínio', 'felony', 120, 75000, '#f9b115', 'Provocar a morte de pessoa durante ou em razão da prática de roubo patrimonial.', 'Crimes Patrimoniais'),
('PAT. 4027', 'Tentativa de Latrocínio', 'felony', 100, 50000, '#f9b115', 'Praticar roubo acompanhado de conduta diretamente destinada a causar a morte da vítima, não ocorrendo o resultado morte.', 'Crimes Patrimoniais'),
('PAT. 4028', 'Extorsão', 'felony', 40, 10000, '#f9b115', 'Constranger pessoa mediante violência ou grave ameaça a entregar dinheiro, bem, direito ou vantagem econômica.', 'Crimes Patrimoniais'),
('PAT. 4029', 'Extorsão mediante Arma', 'felony', 55, 15000, '#f9b115', 'Constranger pessoa mediante utilização de arma para obter dinheiro, bem ou vantagem econômica indevida.', 'Crimes Patrimoniais'),
('PAT. 4030', 'Extorsão mediante Sequestro', 'felony', 90, 30000, '#f9b115', 'Privar pessoa de sua liberdade com objetivo de exigir pagamento, resgate ou vantagem patrimonial.', 'Crimes Patrimoniais'),
('PAT. 4031', 'Apropriação Indébita', 'felony', 20, 5000, '#f9b115', 'Apropriar-se deliberadamente de dinheiro ou bem recebido legitimamente, passando a tratá-lo como próprio sem autorização.', 'Crimes Patrimoniais'),
('PAT. 4032', 'Apropriação de Bem Encontrado', 'misdemeanor', 7, 1500, '#f91521', 'Apropriar-se de bem encontrado pertencente a terceiro quando for possível identificar ou localizar seu proprietário.', 'Crimes Patrimoniais'),
('PAT. 4033', 'Desvio de Bem Confiado', 'felony', 25, 6000, '#f9b115', 'Desviar, vender, ocultar ou utilizar em benefício próprio bem confiado para guarda, transporte ou administração.', 'Crimes Patrimoniais'),
('PAT. 4034', 'Estelionato', 'felony', 30, 7500, '#f9b115', 'Obter vantagem econômica ilícita induzindo ou mantendo outra pessoa em erro mediante fraude ou artifício.', 'Crimes Patrimoniais'),
('PAT. 4035', 'Estelionato mediante Falsa Identidade', 'felony', 35, 10000, '#f9b115', 'Utilizar identidade falsa ou identidade de terceiro para induzir vítima em erro e obter vantagem patrimonial.', 'Crimes Patrimoniais');
INSERT INTO `mdt_penal_codes` (`code`, `label`, `charge_class`, `months`, `fine`, `color`, `description`, `category`) VALUES
('PAT. 4036', 'Fraude em Compra ou Venda', 'felony', 25, 6000, '#f9b115', 'Enganar deliberadamente comprador ou vendedor sobre bem, preço, pagamento ou condições de negócio para obter vantagem indevida.', 'Crimes Patrimoniais'),
('PAT. 4037', 'Fraude em Serviço', 'felony', 20, 5000, '#f9b115', 'Obter ou fornecer serviço mediante engano deliberado com intenção de obter vantagem patrimonial ilícita.', 'Crimes Patrimoniais'),
('PAT. 4038', 'Golpe de Falso Pagamento', 'felony', 30, 7500, '#f9b115', 'Apresentar pagamento, comprovante ou transferência falsa com objetivo de obter produto, dinheiro ou serviço.', 'Crimes Patrimoniais'),
('PAT. 4039', 'Fraude Bancária', 'felony', 45, 12500, '#f9b115', 'Utilizar fraude, dados falsos ou meio enganoso para movimentar, obter ou desviar valores pertencentes a instituição financeira ou terceiro.', 'Crimes Patrimoniais'),
('PAT. 4040', 'Fraude com Cartão ou Meio de Pagamento', 'felony', 35, 10000, '#f9b115', 'Utilizar cartão, conta, credencial ou meio de pagamento de forma fraudulenta para obter vantagem patrimonial.', 'Crimes Patrimoniais'),
('PAT. 4041', 'Fraude em Empréstimo', 'felony', 30, 7500, '#f9b115', 'Utilizar informações ou documentos falsos para obter empréstimo, crédito ou vantagem financeira.', 'Crimes Patrimoniais'),
('PAT. 4042', 'Fraude em Seguro', 'felony', 30, 7500, '#f9b115', 'Criar, simular ou alterar situação com objetivo de receber indevidamente pagamento ou benefício decorrente de seguro.', 'Crimes Patrimoniais'),
('PAT. 4043', 'Venda Fraudulenta de Bem', 'felony', 30, 7500, '#f9b115', 'Vender ou oferecer bem inexistente, pertencente a terceiro ou cuja situação seja deliberadamente ocultada para obter vantagem econômica.', 'Crimes Patrimoniais'),
('PAT. 4044', 'Receptação', 'felony', 25, 6000, '#f9b115', 'Adquirir, receber, transportar, ocultar ou manter bem sabendo que é produto de crime patrimonial.', 'Crimes Patrimoniais'),
('PAT. 4045', 'Receptação de Veículo', 'felony', 35, 10000, '#f9b115', 'Adquirir, receber, ocultar ou manter veículo sabendo que é produto de roubo ou furto.', 'Crimes Patrimoniais'),
('PAT. 4046', 'Comercialização de Produto Roubado ou Furtado', 'felony', 35, 10000, '#f9b115', 'Vender, trocar ou distribuir conscientemente bem proveniente de roubo ou furto.', 'Crimes Patrimoniais'),
('PAT. 4047', 'Dano ao Patrimônio Privado', 'misdemeanor', 10, 2500, '#f91521', 'Destruir, danificar ou inutilizar deliberadamente bem pertencente a outra pessoa.', 'Crimes Patrimoniais'),
('PAT. 4048', 'Dano Patrimonial Grave', 'felony', 25, 7500, '#f9b115', 'Destruir ou danificar deliberadamente patrimônio de elevado valor ou causar prejuízo econômico significativo.', 'Crimes Patrimoniais'),
('PAT. 4049', 'Destruição de Veículo de Terceiro', 'felony', 25, 7500, '#f9b115', 'Destruir, incendiar ou inutilizar deliberadamente veículo pertencente a terceiro.', 'Crimes Patrimoniais'),
('PAT. 4050', 'Ocultação ou Destruição de Bem para Fraudar Proprietário', 'felony', 30, 10000, '#f9b115', 'Ocultar, destruir, transferir ou simular situação envolvendo bem patrimonial com objetivo de enganar proprietário ou terceiro e obter vantagem econômica.', 'Crimes Patrimoniais'),
('V.C. 1001', 'Estacionar em Local Proibido', 'infraction', 0, 130, '#15f943', 'Estacionar veículo em local onde a sinalização ou regulamentação proíba o estacionamento.', 'Veículos e Trânsito'),
('V.C. 1002', 'Estacionar Sobre a Calçada', 'infraction', 0, 195, '#15f943', 'Estacionar veículo sobre calçada, passeio público ou área destinada exclusivamente à circulação de pedestres.', 'Veículos e Trânsito'),
('V.C. 1003', 'Bloqueio de Garagem ou Acesso', 'infraction', 0, 130, '#15f943', 'Estacionar veículo impedindo ou dificultando a entrada ou saída de garagem, propriedade ou acesso autorizado.', 'Veículos e Trânsito'),
('V.C. 1004', 'Estacionar em Vaga Reservada', 'infraction', 0, 293, '#15f943', 'Estacionar em vaga reservada ou especial sem possuir autorização para sua utilização.', 'Veículos e Trânsito'),
('V.C. 1005', 'Obstrução da Circulação por Estacionamento', 'infraction', 0, 195, '#15f943', 'Estacionar veículo de forma a obstruir ou prejudicar a circulação normal de outros veículos.', 'Veículos e Trânsito'),
('V.C. 1006', 'Abandono de Veículo em Via Pública', 'infraction', 0, 195, '#15f943', 'Abandonar veículo em via pública de forma irregular ou prejudicando o trânsito.', 'Veículos e Trânsito'),
('V.C. 1007', 'Parada Irregular no Meio da Via', 'infraction', 0, 130, '#15f943', 'Parar veículo no meio da via sem motivo justificável, emergência ou necessidade relacionada ao trânsito.', 'Veículos e Trânsito'),
('V.C. 1008', 'Parar Sobre Faixa de Pedestres', 'infraction', 0, 130, '#15f943', 'Parar veículo sobre faixa destinada à travessia de pedestres.', 'Veículos e Trânsito'),
('V.C. 1009', 'Avanço de Sinal Vermelho', 'infraction', 0, 293, '#15f943', 'Avançar sinal vermelho de semáforo ou dispositivo equivalente de controle de tráfego.', 'Veículos e Trânsito'),
('V.C. 1010', 'Desrespeito à Parada Obrigatória', 'infraction', 0, 293, '#15f943', 'Deixar de realizar parada obrigatória diante de placa, sinalização ou dispositivo que determine a parada.', 'Veículos e Trânsito'),
('V.C. 1011', 'Desobediência à Ordem de Agente de Trânsito', 'infraction', 0, 195, '#15f943', 'Deixar de cumprir determinação legítima de agente público responsável pelo controle ou fiscalização do trânsito.', 'Veículos e Trânsito'),
('V.C. 1012', 'Condução na Contramão', 'infraction', 0, 195, '#15f943', 'Conduzir veículo no sentido contrário ao fluxo regulamentado da via.', 'Veículos e Trânsito'),
('V.C. 1013', 'Conversão Proibida', 'infraction', 0, 195, '#15f943', 'Realizar conversão em local onde a manobra seja proibida pela sinalização ou regulamentação.', 'Veículos e Trânsito'),
('V.C. 1014', 'Retorno em Local Proibido', 'infraction', 0, 195, '#15f943', 'Realizar retorno em local onde a manobra seja proibida ou represente risco ao trânsito.', 'Veículos e Trânsito'),
('V.C. 1015', 'Condução Sobre Calçada ou Área de Pedestres', 'infraction', 0, 880, '#15f943', 'Conduzir veículo sobre calçada, passeio público ou espaço destinado exclusivamente a pedestres sem justificativa.', 'Veículos e Trânsito'),
('V.C. 1016', 'Ultrapassagem em Local Proibido', 'infraction', 0, 1467, '#15f943', 'Realizar ultrapassagem em trecho, faixa ou situação onde a manobra seja proibida.', 'Veículos e Trânsito'),
('V.C. 1017', 'Ultrapassagem Pelo Acostamento', 'infraction', 0, 1467, '#15f943', 'Utilizar acostamento ou área não destinada à circulação regular para realizar ultrapassagem.', 'Veículos e Trânsito'),
('V.C. 1018', 'Forçar Passagem Entre Veículos', 'infraction', 0, 2935, '#15f943', 'Forçar passagem entre veículos ou contra fluxo contrário, colocando terceiros em situação de risco.', 'Veículos e Trânsito'),
('V.C. 1019', 'Não Dar Preferência ao Pedestre', 'infraction', 0, 195, '#15f943', 'Deixar de conceder preferência de passagem a pedestre quando exigido pelas regras de trânsito.', 'Veículos e Trânsito'),
('V.C. 1020', 'Direção Ameaçadora', 'felony', 5, 293, '#f9b115', 'Conduzir veículo de forma deliberadamente ameaçadora contra pedestres, ciclistas ou outros veículos.', 'Veículos e Trânsito'),
('V.C. 1021', 'Excesso de Velocidade Até 20%', 'infraction', 0, 130, '#15f943', 'Conduzir veículo acima do limite regulamentado da via em percentual de até vinte por cento.', 'Veículos e Trânsito'),
('V.C. 1022', 'Excesso de Velocidade de 20% a 50%', 'infraction', 0, 195, '#15f943', 'Conduzir veículo acima do limite regulamentado da via em percentual superior a vinte e de até cinquenta por cento.', 'Veículos e Trânsito'),
('V.C. 1023', 'Excesso de Velocidade Superior a 50%', 'infraction', 0, 880, '#15f943', 'Conduzir veículo em velocidade superior a cinquenta por cento acima do limite regulamentado da via.', 'Veículos e Trânsito'),
('V.C. 1024', 'Velocidade Incompatível com o Local', 'infraction', 0, 195, '#15f943', 'Conduzir veículo em velocidade incompatível com as condições da via, fluxo, visibilidade ou segurança do local.', 'Veículos e Trânsito'),
('V.C. 1025', 'Arrancada Brusca ou Manobra Perigosa', 'infraction', 0, 2935, '#15f943', 'Realizar arrancada brusca, aceleração agressiva ou outra manobra deliberadamente perigosa em via pública.', 'Veículos e Trânsito'),
('V.C. 1026', 'Drift ou Derrapagem em Via Pública', 'infraction', 0, 2935, '#15f943', 'Provocar intencionalmente derrapagem, deslizamento ou drift em via pública, colocando o trânsito em risco.', 'Veículos e Trânsito'),
('V.C. 1027', 'Manobra Perigosa', 'infraction', 0, 2935, '#15f943', 'Realizar manobra com veículo capaz de gerar risco relevante a pedestres, passageiros ou demais condutores.', 'Veículos e Trânsito'),
('V.C. 1028', 'Empinar Motocicleta', 'infraction', 0, 293, '#15f943', 'Conduzir motocicleta utilizando apenas uma roda ou realizando manobra semelhante em via pública.', 'Veículos e Trânsito'),
('V.C. 1029', 'Disputa de Corrida ou Racha', 'felony', 15, 2935, '#f9b115', 'Participar de corrida, disputa automobilística ou competição de velocidade não autorizada em via pública.', 'Veículos e Trânsito'),
('V.C. 1030', 'Organização de Corrida Ilegal', 'felony', 20, 2935, '#f9b115', 'Promover, organizar ou coordenar corrida, racha ou competição automobilística ilegal em via pública.', 'Veículos e Trânsito'),
('V.C. 1031', 'Participação em Competição Automobilística Ilegal', 'felony', 10, 2935, '#f9b115', 'Participar de evento ou competição automobilística não autorizada realizada em via pública.', 'Veículos e Trânsito'),
('V.C. 1032', 'Bloqueio de Via para Evento Ilegal', 'misdemeanor', 10, 5869, '#f91521', 'Bloquear ou restringir deliberadamente via pública para realização de corrida, encontro ou evento automobilístico ilegal.', 'Veículos e Trânsito'),
('V.C. 1033', 'Condução Sob Influência de Álcool', 'felony', 15, 2935, '#f9b115', 'Conduzir veículo sob influência de bebida alcoólica em condições capazes de comprometer a capacidade de direção.', 'Veículos e Trânsito'),
('V.C. 1034', 'Condução Sob Influência de Drogas', 'felony', 20, 2935, '#f9b115', 'Conduzir veículo sob influência de droga ou substância psicoativa capaz de comprometer a capacidade de direção.', 'Veículos e Trânsito'),
('V.C. 1035', 'Conduzir Sem Habilitação', 'infraction', 0, 880, '#15f943', 'Conduzir veículo automotor sem possuir habilitação válida exigida para a categoria correspondente.', 'Veículos e Trânsito'),
('V.C. 1036', 'Conduzir com Habilitação Suspensa ou Cassada', 'felony', 5, 880, '#f9b115', 'Conduzir veículo enquanto o direito de dirigir estiver suspenso, cassado ou legalmente impedido.', 'Veículos e Trânsito'),
('V.C. 1037', 'Conduzir Veículo Sem Placa', 'infraction', 0, 293, '#15f943', 'Conduzir veículo sem placa de identificação obrigatória ou sem elemento necessário para sua identificação.', 'Veículos e Trânsito'),
('V.C. 1038', 'Uso de Placa Falsa ou Adulterada', 'felony', 20, 5000, '#f9b115', 'Utilizar, instalar ou manter em circulação veículo com placa falsa, clonada, adulterada ou pertencente a outro veículo.', 'Veículos e Trânsito'),
('V.C. 1039', 'Condução de Veículo Roubado ou Furtado', 'felony', 35, 7500, '#f9b115', 'Conduzir ou manter sob posse veículo com conhecimento de que seja produto de roubo ou furto.', 'Veículos e Trânsito'),
('V.C. 1040', 'Adulteração de Identificação Veicular', 'felony', 30, 7500, '#f9b115', 'Adulterar, remover, substituir ou modificar elemento utilizado para identificação oficial de veículo.', 'Veículos e Trânsito'),
('V.C. 1041', 'Fuga de Abordagem Policial', 'felony', 20, 5000, '#f9b115', 'Utilizar veículo para fugir deliberadamente de ordem legítima de parada ou abordagem realizada por autoridade policial.', 'Veículos e Trânsito'),
('V.C. 1042', 'Rompimento de Bloqueio Policial', 'felony', 15, 293, '#f9b115', 'Romper, atravessar ou desobedecer bloqueio policial ou ponto de fiscalização devidamente estabelecido.', 'Veículos e Trânsito'),
('V.C. 1043', 'Uso de Veículo para Ameaçar Terceiros', 'felony', 30, 7500, '#f9b115', 'Utilizar veículo deliberadamente como instrumento para ameaçar, intimidar, ferir ou colocar terceiros em grave risco.', 'Veículos e Trânsito'),
('V.C. 1044', 'Evasão do Local de Acidente', 'felony', 10, 1467, '#f9b115', 'Abandonar ou evadir-se do local de acidente de trânsito com objetivo de evitar responsabilização ou identificação.', 'Veículos e Trânsito'),
('V.C. 1045', 'Omissão de Socorro em Acidente', 'felony', 20, 1467, '#f9b115', 'Deixar injustificadamente de prestar ou solicitar assistência necessária após envolvimento em acidente com pessoa ferida.', 'Veículos e Trânsito'),
('V.C. 1046', 'Transporte de Drogas Ilícitas em Veículo', 'felony', 50, 10000, '#f9b115', 'Transportar ou ocultar substâncias ilícitas dentro de veículo com conhecimento de sua existência.', 'Veículos e Trânsito'),
('V.C. 1047', 'Veículo Utilizado para Tráfico de Drogas', 'felony', 70, 15000, '#f9b115', 'Utilizar veículo para transportar, distribuir, entregar ou auxiliar atividade relacionada ao tráfico de substâncias ilícitas.', 'Veículos e Trânsito'),
('V.C. 1048', 'Transporte de Armamento Ilegal', 'felony', 60, 12500, '#f9b115', 'Transportar ou ocultar em veículo arma, armamento ou munição cuja posse ou circulação seja ilegal.', 'Veículos e Trânsito'),
('V.C. 1049', 'Veículo Utilizado na Prática de Crime', 'felony', 40, 10000, '#f9b115', 'Utilizar veículo como meio, instrumento, apoio ou mecanismo de fuga durante a prática de atividade criminosa.', 'Veículos e Trânsito'),
('V.C. 1050', 'Bloqueio Veicular de Operação Policial', 'felony', 30, 7500, '#f9b115', 'Utilizar veículo deliberadamente para bloquear, impedir, dificultar ou interferir em operação ou perseguição policial.', 'Veículos e Trânsito');
