INSERT INTO `mdt_report_templates` (`id`, `name`, `type`, `content`, `job_type`, `created_at`, `updated_at`) VALUES
(1, 'Incidente padrão', 'Incident Report', '<h2>Resumo do incidente</h2>\n<p>Em [DATA], aproximadamente às [HORÁRIO], [NOME/MATRÍCULA DO AGENTE] atendeu uma ocorrência em [LOCAL] relacionada a [TIPO DE INCIDENTE].</p>\n\n<h2>Detalhes do incidente</h2>\n<p>[DESCREVA A CENA E OS FATOS EM ORDEM CRONOLÓGICA.]</p>\n\n<h2>Partes envolvidas</h2>\n<p><strong>Comunicante:</strong> [NOME E CONTATO]</p>\n<p><strong>Suspeito(s):</strong> [NOME/DESCRIÇÃO]</p>\n<p><strong>Vítima(s):</strong> [NOME]</p>\n<p><strong>Testemunha(s):</strong> [NOME E RESUMO DO DEPOIMENTO]</p>\n\n<h2>Evidências coletadas</h2>\n<ul><li>[ITEM 1 - DESCRIÇÃO E LOCAL ONDE FOI ENCONTRADO]</li><li>[ITEM 2 - DESCRIÇÃO E LOCAL ONDE FOI ENCONTRADO]</li></ul>\n\n<h2>Providências adotadas</h2>\n<p>[DESCREVA PRISÕES, AUTUAÇÕES, ATENDIMENTO MÉDICO E DEMAIS PROVIDÊNCIAS.]</p>\n\n<h2>Conclusão</h2>\n<p>[SITUAÇÃO DO CASO E PROVIDÊNCIAS PENDENTES.]</p>', 'all', 1788795627000.0, 1788795627000.0),
(2, 'Ocorrência de trânsito', 'Traffic Report', '<h2>Resumo da ocorrência de trânsito</h2>\n<p>Em [DATA], aproximadamente às [HORÁRIO], [NOME/MATRÍCULA DO AGENTE] atendeu uma ocorrência de trânsito em [LOCAL/CRUZAMENTO].</p>\n\n<h2>Veículos envolvidos</h2>\n<p><strong>Veículo 1:</strong> [MODELO] - Placa: [PLACA] - Condutor: [NOME]</p>\n<p><strong>Veículo 2:</strong> [MODELO] - Placa: [PLACA] - Condutor: [NOME]</p>\n\n<h2>Descrição da ocorrência</h2>\n<p>[DESCREVA COMO OCORREU, SENTIDO DOS VEÍCULOS, VELOCIDADE E CONDIÇÕES DA VIA E DO TEMPO.]</p>\n\n<h2>Feridos</h2>\n<p>[DESCREVA OS FERIMENTOS, O ATENDIMENTO REALIZADO E O DESTINO DO TRANSPORTE.]</p>\n\n<h2>Autuações emitidas</h2>\n<ul><li>[CONDUTOR] - [CÓDIGO DA INFRAÇÃO] - [DESCRIÇÃO]</li></ul>\n\n<h2>Testemunhas</h2>\n<p>[NOME]: [RESUMO DO DEPOIMENTO]</p>\n\n<h2>Observações adicionais</h2>\n<p>[DESCREVA A DISPOSIÇÃO DA CENA OU INDIQUE O DIAGRAMA ANEXADO.]</p>', 'all', 1788795627000.0, 1788795627000.0),
(3, 'Relatório de investigação', 'Investigation Report', '<h2>Visão geral do caso</h2>\n<p><strong>Número do caso:</strong> [NÚMERO]</p>\n<p><strong>Investigador responsável:</strong> [NOME/MATRÍCULA]</p>\n<p><strong>Data de abertura:</strong> [DATA]</p>\n<p><strong>Classificação:</strong> [CRIME/CONTRAVENÇÃO/OUTRO]</p>\n\n<h2>Contexto</h2>\n<p>[DESCREVA O MOTIVO DA INVESTIGAÇÃO E CITE RELATÓRIOS ANTERIORES RELACIONADOS.]</p>\n\n<h2>Pessoas de interesse</h2>\n<p><strong>Suspeito 1:</strong> [NOME, DESCRIÇÃO, ASSOCIADOS E ÚLTIMO LOCAL CONHECIDO]</p>\n<p><strong>Suspeito 2:</strong> [NOME E DESCRIÇÃO]</p>\n\n<h2>Resumo das evidências</h2>\n<ul><li>[DESCRIÇÃO DA EVIDÊNCIA]</li><li>[DESCRIÇÃO DA EVIDÊNCIA]</li></ul>\n\n<h2>Linha do tempo</h2>\n<ul><li><strong>[DATA/HORÁRIO]:</strong> [EVENTO]</li><li><strong>[DATA/HORÁRIO]:</strong> [EVENTO]</li></ul>\n\n<h2>Entrevistas realizadas</h2>\n<p><strong>[NOME]:</strong> [RESUMO DA ENTREVISTA]</p>\n\n<h2>Conclusões e recomendações</h2>\n<p>[RESUMA AS CONCLUSÕES E RECOMENDE AS PRÓXIMAS PROVIDÊNCIAS.]</p>', 'all', 1788795627000.0, 1788795627000.0),
(4, 'Relatório de prisão', 'Arrest Report', '<h2>Resumo da prisão</h2>\n<p>Em [DATA], aproximadamente às [HORÁRIO], [NOME/MATRÍCULA DO AGENTE] prendeu [NOME DO SUSPEITO] em [LOCAL].</p>\n\n<h2>Dados do suspeito</h2>\n<p><strong>Nome:</strong> [NOME COMPLETO]</p>\n<p><strong>ID do cidadão:</strong> [ID]</p>\n<p><strong>Descrição:</strong> [DESCRIÇÃO]</p>\n\n<h2>Fundada suspeita</h2>\n<p>[DESCREVA AS CIRCUNSTÂNCIAS E EVIDÊNCIAS QUE JUSTIFICARAM A PRISÃO.]</p>\n\n<h2>Acusações</h2>\n<ul><li>[CÓDIGO E DESCRIÇÃO]</li><li>[CÓDIGO E DESCRIÇÃO]</li></ul>\n\n<h2>Narrativa</h2>\n<p>[RELATO CRONOLÓGICO DOS FATOS QUE LEVARAM À PRISÃO.]</p>\n\n<h2>Evidências apreendidas</h2>\n<ul><li>[ITEM E DESCRIÇÃO]</li></ul>\n\n<h2>Direitos de Miranda</h2>\n<p>Os direitos foram lidos ao suspeito às [HORÁRIO]. O suspeito [SOLICITOU/NÃO SOLICITOU] advogado e [FORNECEU/NÃO FORNECEU] declaração.</p>\n\n<h2>Processamento</h2>\n<p>O suspeito foi registrado em [UNIDADE] às [HORÁRIO]. [INFORMAÇÕES SOBRE FIANÇA OU RETENÇÃO.]</p>', 'all', 1788795627000.0, 1788795627000.0),
(5, 'Relatório de evidências', 'Evidence Report', '<h2>Resumo das evidências</h2>\n<p><strong>Caso relacionado:</strong> [NÚMERO DO CASO]</p>\n<p><strong>Agente responsável pela coleta:</strong> [NOME/MATRÍCULA]</p>\n<p><strong>Data da coleta:</strong> [DATA]</p>\n<p><strong>Local:</strong> [LOCAL DA COLETA]</p>\n\n<h2>Itens coletados</h2>\n<h3>Item 1</h3>\n<p><strong>Descrição:</strong> [DESCRIÇÃO DETALHADA]</p>\n<p><strong>Número de série/ID:</strong> [SE APLICÁVEL]</p>\n<p><strong>Local onde foi encontrado:</strong> [POSIÇÃO EXATA NA CENA]</p>\n<p><strong>Condição:</strong> [CONDIÇÃO AO SER ENCONTRADO]</p>\n<p><strong>Armazenamento:</strong> [ARMÁRIO/ID DO DEPÓSITO]</p>\n\n<h3>Item 2</h3>\n<p><strong>Descrição:</strong> [DESCRIÇÃO DETALHADA]</p>\n<p><strong>Local onde foi encontrado:</strong> [POSIÇÃO EXATA NA CENA]</p>\n<p><strong>Armazenamento:</strong> [ARMÁRIO/ID DO DEPÓSITO]</p>\n\n<h2>Cadeia de custódia</h2>\n<ul><li><strong>[DATA/HORÁRIO]:</strong> Coletado por [NOME] em [LOCAL]</li><li><strong>[DATA/HORÁRIO]:</strong> Transferido para [NOME/UNIDADE]</li></ul>\n\n<h2>Análise solicitada</h2>\n<p>[DESCREVA A ANÁLISE LABORATORIAL OU O EXAME FORENSE SOLICITADO.]</p>\n\n<h2>Observações</h2>\n<p>[INFORMAÇÕES ADICIONAIS RELEVANTES.]</p>', 'all', 1788795627000.0, 1788795627000.0);
