INSERT INTO `mdt_sop_sections` (`id`, `category_id`, `title`, `content`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'Código de Ética', '<p>O Código de Ética estabelece um conjunto de valores e princípios em que todo o trabalho do departamento deve ser feito dentro. A violação de qualquer uma das éticas pode levar a queixas, ação disciplinar que pode incluir demissão.</p><p>Ao se tornar um oficial da lei, você ganha muitas responsabilidades, incluindo o poder e a capacidade de cumprir a lei. Dentro da lei você tem muito poder para prender, acusar e procurar civis. Todos estes devem estar dentro das leis do Estado. Qualquer falha em seguir oficiais superiores pode levar à Disciplina de Comando. A capacidade que é dada aos LEOs não pode ser abusada ou ser utilizada de forma diversa, caso contrário, podem ser tomadas medidas disciplinares.</p><ul><li>Profissionalismo</li><li>Responsabilidade</li><li>Respeito</li><li>Liderança</li></ul><p>Nunca agirei oficiamente ou permitirei que sentimentos pessoais, preconceitos, animosidades ou amizades influenciem minhas decisões. Sem compromisso para o crime e com a acusação implacável de criminosos, vou aplicar a lei com cortesia e apropriadamente sem medo ou favor, malícia ou má vontade, nunca empregando força desnecessária ou violência e nunca aceitar gratificações.</p><p>Reconheço o distintivo do meu gabinete como símbolo da fé pública, e aceito-o como uma confiança pública a ser mantida desde que seja fiel à ética do serviço policial. Sempre me esforçarei para alcançar esses objetivos e ideais, dedicando-me diante de Deus à minha profissão escolhida... Polícia.</p>', 1, 1788795627000.0, 1788795627000.0),
(2, 2, 'Juramento de Estado', '<p><em>"Juro solenemente: Apoiarei, protegerei e defenderei a Constituição e o Governo dos Estados Unidos e do Estado; prestarei estrita obediência aos meus superiores na Agência de Execução da Lei, e observarei e cumprirei todas as ordens e regulamentos por eles prescritos para o governo e administração da referida Patrulha; sempre me comportarei sobriedade, honra e honestamente; manterei estrita, pontual e constante atenção aos meus deveres; abster-me-ei de toda personalidade ofensiva ou conduta imprópria para um Oficial de Execução da Lei; cumprirei minhas funções destemidamente, imparcialmente e com toda a devida cortesia e cumprirei com toda a fidelidade os deveres de um Oficial de Execução da Lei sobre o qual estou agora prestes a entrar. Que Deus me ajude."</em></p>', 1, 1788795627000.0, 1788795627000.0),
(3, 3, 'Equipamento e preparação', '<ul><li><strong>Os agentes responsáveis pela aplicação da lei devem dispor de todo o equipamento adequado para desempenhar funções policiais.</strong></li><li><strong>Os agentes de aplicação da lei devem ter todos os equipamentos disponíveis e prontos para utilização.</strong></li><li><strong>Os agentes responsáveis pela aplicação da lei devem assegurar que o veículo dispõe de equipamento adequado e é passível de manutenção.</strong></li><li><strong>Os agentes da lei devem garantir que todas as armas sejam carregadas e servidas.</strong></li><li><strong>Os agentes da lei devem atender a todas as chamadas.</strong></li><li><strong>Os agentes da lei seguirão a cadeia de comando adequada.</strong></li><li><strong>Os agentes responsáveis pela aplicação da lei devem assegurar-se de que agem de forma segura.</strong></li></ul>', 1, 1788795627000.0, 1788795627000.0),
(4, 4, 'Normas de Conduta do Oficial', '<ul><li>Os agentes policiais devem manter os rolamentos profissionais o tempo todo.</li><li>Os agentes da lei nunca devem assediar, intimidar ou violar os direitos de qualquer civil.</li><li>Os agentes policiais nunca devem abusar de seu poder para beneficiar-se ou ferir outros de qualquer forma. (Fisicamente, fisicamente, verbalmente ou de qualquer forma que esteja abaixo do juramento de um Oficial para proteger e servir.)</li><li>Os agentes de aplicação da lei devem ajudar todos os civis que necessitem do melhor possível.</li><li>Os agentes de aplicação da lei devem obedecer a qualquer ordem legal emitida por um supervisor de posto superior ao deles.</li><li>Os agentes de aplicação da lei são responsáveis por qualquer dano que cause a uma pessoa fora do Estado de direito e de acordo com o guia de patrulha de cada departamento.</li><li>Os agentes da lei devem e vão seguir todas as leis rodoviárias e não abusar das sirenes para ignorar essas leis.</li><li>Os agentes responsáveis pela aplicação da lei devem poder justificar qualquer uso da força ou da causa para uma detenção/parada de qualquer pessoa.</li><li>Os agentes responsáveis pela aplicação da lei não discriminarão qualquer pessoa por qualquer razão, incluindo, mas não se limitando a: Raça, religião, orientação sexual e gênero.</li></ul>', 1, 1788795627000.0, 1788795627000.0),
(5, 5, 'Disciplinas de Comando', '<p>Disciplinas de Comando são recomendadas para má conduta que é mais problemática do que treinamento ruim, mas não sobe para o nível de encargos. Disciplinas de comando serão emitidas a todos os oficiais de aplicação da lei que violarem regulamentos ou não obedecerem a uma ordem legal de um supervisor, também conhecido como insubordinação.</p><p>Policiais podem acumular-se até<strong>(3)</strong>Disciplinas de Comando antes de terminar o departamento. Os agentes de aplicação da lei podem ser rescindidos também dependendo do nível do crime ou ofensas cometidas; isso depende do pessoal de comando e aprovado pelo Comissário.</p><p><strong>Nota:</strong>Um Verbal e Escrito devido à repetição da mesma má conduta será igual a uma Final.</p><p>(Verbal, Escrito, Final) são os CDs a que se referem.</p>', 1, 1788795627000.0, 1788795627000.0),
(6, 5, 'Suspensão e encerramento', '<p>Os agentes policiais estão sujeitos à suspensão de qualquer CD escrito com base na discrição do supervisor.</p><p>A rescisão é a resposta final aos problemas de comportamento de um agente da lei. Os oficiais serão formalmente soltos pelo departamento e isso é decidido pelo supervisor. Agentes de condicional, ainda em andamento, podem ser encerrados por um SGT/LT.</p>', 2, 1788795627000.0, 1788795627000.0),
(7, 5, 'Regras e assistência', '<p><strong>Regras:</strong>Todas as regras, políticas e procedimentos se aplicam aos LEO em todos os momentos.</p><p><strong>Política de participação:</strong>Policiais que estão ativos são muito apreciados, mas como todos sabemos nossas vidas e família são mais importantes. Os agentes que estarão ocupados devem avisar o pessoal de comando.</p><p><strong>Conduta Proibida:</strong></p><ul><li>Consumo de estupefacientes e álcool em serviço = ENCERRAMENTO</li><li>Envolvendo-se em discussão com outros membros enquanto intoxicado IRL em um canal de patrulha.</li></ul>', 3, 1788795627000.0, 1788795627000.0),
(8, 6, 'Direito a uma Autoridade', '<p>Os cidadãos têm o direito de falar com um supervisor. Quando um supervisor é solicitado por um civil, espera-se que ele responda à chamada quando estiver disponível.</p><p>Os detidos têm também o direito de falar com um supervisor, caso o solicitem. Se um supervisor for solicitado por um suspeito a ser preso, pode ser levado para o Departamento de Polícia ou para o local atual para esperar por um. <strong>Mas, eles não devem receber nenhuma acusação criminal até que o supervisor tenha falado com eles.</strong></p><p><strong>O direito a um supervisor só pode ser recusado nas seguintes situações:</strong></p><ul><li>O Supervisor esteve anteriormente envolvido no caso do suspeito e confirmou que o suspeito será acusado.</li><li>Se o agente de detenção já for um Supervisor. Por exemplo, o sargento não tem que pedir a um tenente ou outro supervisor para falar com seu suspeito se o suspeito pedir.</li><li>Não há supervisores disponíveis.</li><li>Se não houver supervisores em Duty, qualquer ACL pode assumir o papel do supervisor e falar com o suspeito como um assistente de treinamento de campo.</li></ul>', 1, 1788795627000.0, 1788795627000.0),
(9, 6, 'Receber e responder às chamadas', '<p><strong>Recebendo uma chamada de emergência:</strong>Sempre reconheça a chamada, se enviada por despacho, notificá-los e esclarecer que você está respondendo. Se notificado pelo sistema 911, então avise a todos sobre o canal de tráfego de rádio que você estará respondendo.</p><p><strong>Chegando à cena:</strong>Quando você chegar ao local, avise o despacho e seus colegas de que você chegou ao local. Geralmente, a menos que designado, o primeiro oficial no local será sempre o Oficial responsável (OIC). O primeiro supervisor no local tomará o comando da cena. É sua responsabilidade manter o despacho e/ou outros oficiais informados da situação que se desenrola e levar os suspeitos de volta para a Delegacia.</p>', 2, 1788795627000.0, 1788795627000.0),
(10, 6, 'Cadeia e punição', '<p><strong>Tratamento dos suspeitos:</strong>Se um supervisor é solicitado por um suspeito a ser preso, então eles podem ser levados ao Departamento de Polícia para esperar por um, mas eles não devem receber quaisquer acusações criminais até que o supervisor tenha falado com eles. Por favor, consulte Direito a um Supervisor para quando o direito a um supervisor pode ser negado.</p><p><strong>Castigos:</strong>Os oficiais são esperados para não somar leis e não maximizar as sentenças, a menos que o assunto é o crime. Pequena quebra de leis (por exemplo, infrações de trânsito) deve<strong>NUNCA</strong>ser adicionado para criar uma sentença de prisão maior. Em geral, a extensão ou a cooperação oferecida pelo suspeito devem ser consideradas aquando da fixação de uma pena de prisão ou da emissão de uma multa.</p><ul><li><strong>Oficial de detenção DEVE ler os Direitos de Miranda</strong>Antes de prender ou transportar o sujeito para a Estação. * Em diferentes circunstâncias os direitos de Miranda podem ser lidos na estação.</li><li>Os agentes de detenção têm de explicar as acusações do suspeito antes de prendê-los.</li><li>Os agentes devem soltar o suspeito antes de enviá-los para a prisão.</li><li>Ao transportar um suspeito, o veículo deve incluir uma gaiola de transporte prisional.</li><li>Os suspeitos devem ser revistados antes de serem transportados.</li><li>Os agentes de detenção têm de fazer um relatório sobre o sistema MDT.</li><li><strong>Ao prender um suspeito, o Oficial de Detenção deve usar sempre os Código Penal para as Sentenças e para as Acusações.</strong></li></ul><p>Toda sentença está sujeita à discrição do oficial depois de ter em consideração outros crimes pendentes, status de liberdade condicional, crimes repetidos, ou outras informações obtidas durante a investigação. Os oficiais são encorajados a dar clemência a criminosos cooperativos e não violentos. Todas as cargas são empilháveis e sujeitas a alterações sem aviso prévio.</p><p><strong>Classificação dos crimes:</strong></p><ul><li><strong>Infração</strong>- A menos grave violação do código penal. Resulta em uma multa e/ou perda de um privilégio.</li><li><strong>Contravenção</strong>- Uma pequena violação do código penal. Resultados em prisão, multa e/ou prisão.</li><li><strong>Delito</strong>- Violação grave do código penal. Resultados em prisão, multa e prisão.</li></ul>', 3, 1788795627000.0, 1788795627000.0),
(11, 7, 'Definições de condução de emergência', '<p><strong>Condução de Emergência (Não-Pesquisa):</strong>O funcionamento de um veículo de emergência (luzes vermelhas e azuis de emergência e sirene em funcionamento) por um agente da aplicação da lei em resposta a uma situação de risco de vida ou a um crime violento em curso, tendo devidamente em conta a segurança de outros.</p><p><strong>Condução de perseguição:</strong>Uma tentativa de um oficial da lei operando um veículo de emergência e utilizando simultaneamente luzes vermelhas e azuis e sirene para prender um ocupante de outro veículo em movimento, quando o motorista do veículo em fuga está ciente da tentativa e está resistindo à apreensão, mantendo ou aumentando a velocidade, desobedecendo as Leis de Tráfego, ignorando ou tentando iludir os oficiais da aplicação da lei.</p><p>O(s) agente(s) deve(m) deixar sempre o(s) espaço(s) entre o(s) suspeito(s) e o(s) seu(s) veículo(s) durante a perseguição, em caso de travagem de emergência ou de acidente. A Manobra do Pit só pode ser realizada por Supervisores ou Oficiais Certificados do Pit. A manobra de pit só deve ser realizada se não houver tráfego. A Manobra do Pit nunca deve ser realizada em Áreas Residenciais.</p><p><strong>A seguir:</strong>Condução em proximidade com um veículo sujeito sem utilizar qualquer esforço de apreensão, como luzes vermelhas e azuis ou sirenes, ou qualquer outro método de direção para parar.</p>', 1, 1788795627000.0, 1788795627000.0),
(12, 7, 'Códigos de resposta', '<p><strong>Códigos de resposta às chamadas de emergência:</strong></p><p><strong>Código 1 - Não-Urgente / Sem Luzes, Sem Sereias:</strong>Supervisor chamadas, danos à propriedade, invasão, roubo de propriedade (não em andamento), Jaywalking.</p><p><strong>Código 2 - Alta prioridade / luzes acesas, sem sirenes:</strong>Chamadas de parada de trânsito, luta em progresso, acidentes de carro, tiros disparados na área, roubo de propriedade em andamento.</p><p><strong>Código 3 - Luzes de emergência e sirenes acesas:</strong>Perseguição de Veículos, Oficial para baixo ou em perigo, Roubo Armado, Procurado, Atualização de Homicídios, Tiro Ativo.</p>', 2, 1788795627000.0, 1788795627000.0),
(13, 8, 'Identificação dos agentes', '<p>Os oficiais devem sempre se identificar como policiais durante uma situação e, especialmente, quando entram em um prédio ou durante as Paradas de Tráfego. Caso contrário, os oficiais poderiam estar enganados como pessoas hostis. Os agentes devem também comunicar o seu nome e os seus números de identificação a outros, se solicitado, se a pessoa que os solicita desejar apresentar uma queixa.</p><p><em>* Oficiais disfarçados não são obrigados a identificar-se aos civis se eles estão executando uma investigação.</em></p>', 1, 1788795627000.0, 1788795627000.0),
(14, 8, 'Desempenho dos deveres', '<p><strong>Desempenho negligente dos deveres:</strong>Um oficial que exerce funções, mesmo dentro dos limites da lei, pode ser considerado negligente no desempenho de suas funções, se obviamente não agirem o melhor de sua capacidade ou se seu comportamento colocar em perigo de forma irracional a vida dos cidadãos, outros oficiais, ou de si mesmos, e os riscos, obviamente e pesadamente superam os benefícios.</p><p><strong>Respostas Supervisor às Chamadas:</strong>Espera-se que os supervisores respondam à chamada mais importante na altura e não possam ficar ociosos ou ignorar as funções regulares de policiamento e supervisão, em vez de tarefas mais brandas. <strong>Os supervisores devem responder e julgar todos os incidentes de tiroteio envolvidos em oficiais.</strong></p><ul><li>Os supervisores devem tomar Relatórios de Incidentes (em MDT) de cenas envolvidas de tiro, acidentes oficiais, perseguição de veículos.</li></ul>', 2, 1788795627000.0, 1788795627000.0),
(15, 8, 'Estrutura do mandado', '<p>Para que um mandado seja motivo suficiente para prender alguém e ser classificado como "válido", você precisa fornecer uma visão geral da situação, incluindo evidências e armas usadas (se houver). Mandados apenas dizendo "Tentado para executar o motorista uber sobre" não será classificado como "válido" ou ser suficiente para prender alguém para, como ele não dá uma visão geral da situação, nem nos diz que tipo de evidência estava presente na época. Também é importante especificar se é um mandado de busca ou se é um mandado de prisão.</p><p>Um bom exemplo de mandado de detenção é: <em>"Mandado de prisão: Matou o civil durante o assalto à mão armada a 24 horas por dia com uma Beretta M9. Várias testemunhas, incluindo policiais, testemunharam a situação. Provas encontradas no local."</em></p><p>Um bom exemplo de um mandado de busca é: <em>"Mandado de busca: As plantas de drogas parecem ser visíveis da janela do apartamento, indicando que a produção de drogas está em andamento. O dono do apartamento recusou-se a abrir a porta para os oficiais."</em></p>', 3, 1788795627000.0, 1788795627000.0),
(16, 8, 'Botão de pânico e comando de cena', '<p><strong>Botão de pânico:</strong>O Botão do Pânico só deve ser pressionado quando houver uma preocupação urgente com a segurança pessoal de você ou de um colega, o que requer assistência imediata.</p><ul><li><strong>Todas as unidades devem responder às cenas 10-99. Os supervisores podem cancelar se não forem necessárias mais unidades no local.</strong></li></ul><p><strong>Comando de Cena:</strong>O primeiro sargento ou superior no local será considerado como Comando de Cena. Somente o Comando de Cena pode remover Unidades da Cena Ativa, independentemente do Rank. O Comando Ativo da Cena irá aconselhar os oficiais sobre o que fazer. <strong>Os assistentes de treinamento de campo podem tomar o Scene Command se não houver um supervisor ativo no dever.</strong></p>', 4, 1788795627000.0, 1788795627000.0),
(17, 8, 'Paragem de Tráfego', '<p>No momento de qualquer paragem de trânsito, é e deve ser conhecido como uma cena e será tratado como tal. Embora um policial tenha qualquer pessoa sob investigação por excesso de velocidade, equipamentos inoperáveis e veículos considerados impróprios para as estradas, todos os suspeitos serão atualmente detidos (<strong>eles não têm que estar algemados, eles podem estar em seu veículo</strong>) durante a paragem de trânsito. Talvez não saiam do local, mas talvez chamem um advogado antes do tempo, caso sintam necessidade de fazê - lo. Em nenhum momento durante uma parada de trânsito deve ser usado o uso de força mortal, a menos que um oficial teme por sua vida. Menos do que letal é sempre permitido se a situação surgir.</p><p>Durante uma parada de trânsito, se os comandos dos agentes da lei são dados ao suspeito ou ao acusado e após várias tentativas o suspeito se recusa a cumprir, então vários passos de menos do que a força letal são permitidos. O uso desta força é determinado pelo chefe de departamento. O uso de força mortal não é permitido e resultará na remoção do oficial ou ação disciplinar.</p>', 5, 1788795627000.0, 1788795627000.0),
(18, 8, 'Limites de Velocidade e Roubos', '<p><strong>Limites de velocidade:</strong></p><ul><li>Limites da cidade - 40 MPH</li><li>Rodovias / Fora da Cidade - 80 MPH</li></ul><p><strong>Oficiais Máximos permitidos por roubo:</strong></p><ul><li>Casino Heist: 4</li><li>Roubo ao Pacífico: 5</li><li>Roubo de Jóias: 3</li><li>Roubo à Fleeca: 4</li><li>Roubo à casa: 2</li><li>Roubo à loja: 3</li><li>Roubo de comboio: 4</li><li>Roubo de camiões: 3</li><li>Ativo 10-80s: 3 (carros)</li></ul>', 6, 1788795627000.0, 1788795627000.0),
(19, 8, 'Air One', '<p>Para que um oficial seja certificado como Air One, deve ser treinado e liberado por um Instrutor de Treinamento de Campo. Apenas um Departamento FTI certificado pela Air One pode autorizar outros a serem certificados. Para ser liberado para certificação Air One, seu instrutor de treinamento irá levá-lo através do curso de treinamento Air One, onde você terá que mostrar ao seu instrutor sua capacidade de voar e usar Air One. Só passará se tiver mostrado ao seu instrutor que está pronto. Você também será ensinado a maneira correta de usar Air One.</p><p><strong>Regras:</strong></p><ul><li>O Air One só pode sair durante 30 minutos antes de ter de voltar à MRPD para reabastecer.</li><li>Deve haver um tempo de reabastecimento de 3-5 minutos antes do Air One voltar ao ar ou voltar a uma situação ativa.</li><li>Só é possível soltar pessoas se a área estiver segura (o que significa que ninguém está atirando no Air One).</li></ul>', 7, 1788795627000.0, 1788795627000.0),
(20, 9, 'Utilização da Política de Força', '<p>Os agentes responsáveis pela aplicação da lei podem utilizar qualquer força na execução das suas funções, desde que tal seja razoável e justificável.</p><ul><li><strong>Uma arma de fogo só pode ser utilizada quando existe um perigo claro e presente para a vida e outros métodos não letais são inadequados ou falharam.</strong></li><li><strong>As armas de fogo nunca devem ser utilizadas para prender um suspeito em fuga, a menos que se justifique no ponto acima.</strong></li><li><strong>Os tiros de aviso nunca devem ser disparados.</strong></li><li><strong>Só deverá descarregar a sua arma se tiver uma linha de visão clara e for seguro fazê-lo.</strong>Não efetue disparos cruzados na direção de outros agentes.</li><li><strong>Os agentes que utilizem uma força excessiva na execução das suas funções sem uma razão razoável e justificável podem conduzir a uma ação disciplinar.</strong></li></ul>', 1, 1788795627000.0, 1788795627000.0),
(21, 9, 'Orientações Mortais para a Força', '<p><strong>a) Utilização da força mortal:</strong>Força mortal significa força que é usada contra outro indivíduo, que provavelmente causará sérios danos corporais ou morte ao indivíduo em questão. A utilização de força mortal pode ser utilizada se existir uma ou mais das seguintes circunstâncias:</p><p><strong>1 - Autodefesa:</strong>Quando a força mortal razoavelmente parece ser necessária para proteger um oficial que razoavelmente acredita em si mesmo está em perigo iminente de morte ou dano corporal grave.</p><p><strong>2 - Crimes graves:</strong>Quando a força mortal de forma razoável e objetiva parece ser necessária para proteger o público de uma ofensa grave. Exemplos: O assunto em questão está a conduzir imprudentemente ao ponto em que representa uma ameaça iminente para o público em geral ou para os agentes. Ou o sujeito está atualmente armado com uma arma de fogo e os oficiais acreditam que, sem qualquer dúvida, o sujeito irá usá-lo.</p><p><strong>3 - Pneus:</strong>Os agentes devem apontar para os pneus de um veículo quando for necessário atirar num veículo de condução imprudente em que os ocupantes sejam conhecidos por estarem armados ou sejam um perigo para o público. Uma vez que os pneus foram furados, os agentes devem parar de atirar no veículo.</p><p><strong>4 - Um Aviso:</strong>"POLÍCIA PARE" ou "POLÍCIA, PARE OU VOCÊ SERÁ BOLADO" geralmente deve ser dado se possível antes que o oficial dispare sua arma.</p><p><strong>5 - Veículos:</strong>Em geral, os veículos não devem ser utilizados como arma, a menos que este seja o último recurso do oficial.</p>', 2, 1788795627000.0, 1788795627000.0),
(22, 10, 'Fases de treino', '<p>Quando você se tornar um oficial de aplicação da lei dentro do departamento, você deve passar por 3 estágios de treinamento de campo. Cada estagiário será designado com um oficial de formação em campo ou um assistente de formação em campo. Os estagiários que passarem as 3 etapas do treinamento de campo terão a capacidade de patrulhar sozinhos. Até lá, só podem patrulhar com agentes de patrulha ou FTO.</p>', 1, 1788795627000.0, 1788795627000.0),
(23, 10, 'Direitos Miranda', '<p><em>"Você tem o direito de permanecer em silêncio, qualquer coisa que você diz ou faz pode ser usado contra você em um tribunal de direito, você tem o direito de um advogado. Se não puder pagar um, será nomeado pelo Estado. Compreende os direitos que lhe foram lidos? Com estes direitos em mente, deseja falar comigo?"</em></p>', 2, 1788795627000.0, 1788795627000.0),
(24, 10, 'Advogado Ping', '<p>Quando se prende alguém, tem direito a um advogado presente. Marque os advogados no Discord, na categoria DOJ e no canal #lawyer-ping. Espere uma resposta ou um advogado chegar. Se ninguém chegar depois de 10 minutos, prossiga com a prisão.</p>', 3, 1788795627000.0, 1788795627000.0),
(25, 11, 'Veículos PD', '<p>Os carros de polícia (os que encontrar na garagem) serão distribuídos como carros pessoais. Você pode estacioná-los em suas garagens e fazer upgrades para seus cruzadores pessoais.</p><ul><li>Você não pode mudar as cores ou os viveiros.</li><li>Você pode instalar upgrades para tornar o seu carro mais rápido com qualquer um dos mecânicos na cidade.</li></ul>', 1, 1788795627000.0, 1788795627000.0),
(26, 11, 'Unidade K9', '<p><em>Trabalho em Progresso</em></p>', 2, 1788795627000.0, 1788795627000.0);
INSERT INTO `mdt_sop_settings` (`id`, `job`, `mission_statement`, `introduction`, `version`, `updated_by`, `updated_at`) VALUES
(1, 'police', '<p><strong>Missão</strong></p><p>A missão da aplicação da lei é fornecer serviços de segurança pública eficientes e eficazes aos moradores e visitantes da cidade. Oferecemos esses serviços com caráter, competência e comunicação aberta.</p><p><strong>Valores</strong></p><p>Julgamento, Unidade, Habilidade, Confiança, Ingenuidade, Coragem, Empoderamento =<strong>JUSTIÇA</strong></p><p><strong>M.O.S. Requerimento</strong></p><p>Espera-se que todos os Membros do Serviço (M.O.S.) cumpram em todos os momentos os valores acima mencionados e procedam código de conduta.</p><p>Um briefing deve ser conduzido se houver 4 ou mais policiais no referido departamento pelo seu departamento CS. A legislatura do Departamento ditará os termos dessas instruções.</p>', '<p>Ao acessar este Terminal de Dados Móveis, você reconhece que leu, compreendeu e concorda em seguir todos os Procedimentos Operacionais Padrão estabelecidos pelo Departamento.</p><p>Espera-se que todos os Membros do Serviço mantenham o profissionalismo, mantenham a lei e ajam com integridade em todos os momentos durante o serviço.</p><p>O não cumprimento desses procedimentos pode resultar em ação disciplinar, incluindo, mas não se limitando à suspensão, rebaixamento ou rescisão.</p><p>Se você tiver alguma dúvida sobre esses procedimentos, entre em contato com seu supervisor ou cadeia de comando.</p>', 1, 'Pierre Moraes', 1788842781000.0);
