INSERT INTO `player_mails` (`id`, `citizenid`, `sender`, `subject`, `message`, `read`, `mailid`, `date`, `button`) VALUES
(10, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade Superior a 50%. Local: Sinner Street / Vespucci Boulevard. Velocidade registrada: 96 km/h. Limite: 60 km/h. Valor: R$ 880.', 0, 657177, 1789342952000.0, NULL),
(11, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade Até 20%. Local: Sinner Street / Atlee Street. Velocidade registrada: 63 km/h. Limite: 60 km/h. Valor: R$ 130.', 0, 265195, 1789343237000.0, NULL),
(12, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade Superior a 50%. Local: Sinner Street / Vespucci Boulevard. Velocidade registrada: 100 km/h. Limite: 60 km/h. Valor: R$ 880.', 0, 380506, 1789343345000.0, NULL),
(13, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade Superior a 50%. Local: Palomino Avenue. Velocidade registrada: 175 km/h. Limite: 60 km/h. Valor: R$ 880.', 0, 840449, 1789344139000.0, NULL),
(14, 'RE036OYR', 'Vehicle Impound Unit', 'Vehicle impounded — AD647471', 'Your vehicle AD647471 has been impounded.\n\nReason: sdsd\nHeld at: Air Depot\nRelease fee: $10000\nStorage: $500 per day, up to 7 days\n\nSpeak to an officer to arrange release. The longer it stays with us, the more it will cost you.', 0, 376081, 1789344513000.0, NULL),
(15, 'RE036OYR', 'Vehicle Impound Unit', 'Vehicle released — AD647471', 'Your vehicle AD647471 has been released from the impound lot.\n\nIt is back in your garage.', 0, 907624, 1789344760000.0, NULL),
(16, 'RE036OYR', 'Forge', 'Teste de e-mail', 'Integração PR Bridge funcionando.', 0, 940698, 1789848355000.0, NULL),
(17, 'RE036OYR', 'Forge Polícia', 'Multa veicular', 'Foi emitida uma multa para o veículo de placa AD054294. Valor: R$ 12500. Infrações: V.C. 1038 - Uso de Placa Falsa ou Adulterada, V.C. 1040 - Adulteração de Identificação Veicular. Observação: Veiculo encontrava-se com plafa fria sendo a placa original do veiculo "AD054294"!', 0, 807490, 1789857500000.0, NULL),
(18, 'P567E59I', 'Forge Polícia', 'Multa veicular', 'Foi emitida uma multa para o veículo de placa AD685303. Valor: R$ 130. Infrações: V.C. 1001 - Estacionar em Local Proibido.', 0, 288275, 1789948460000.0, NULL),
(19, 'P567E59I', 'Forge Polícia', 'Multa veicular', 'Foi emitida uma multa para o veículo de placa AD685303. Valor: R$ 12500. Infrações: V.C. 1038 - Uso de Placa Falsa ou Adulterada, V.C. 1040 - Adulteração de Identificação Veicular.', 0, 323042, 1789948651000.0, NULL),
(20, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade Até 20%. Local: Palomino Avenue. Velocidade registrada: 71 km/h. Limite: 60 km/h. Valor: R$ 130.', 0, 363562, 1789951789000.0, NULL),
(21, 'RE036OYR', 'Fiscalização eletrônica', 'Multa de radar de velocidade', 'Infração: Excesso de Velocidade de 20% a 50%. Local: Palomino Avenue / Goma Street. Velocidade registrada: 85 km/h. Limite: 60 km/h. Valor: R$ 195.', 0, 799814, 1789951790000.0, NULL),
